    {
      "path": "src/host/index.ts",
      "content": "/**\n * dsh-web-tools — Host plugin entry.\n *\n * Registers:\n *  - the `dsh-web-tools` settings namespace (non-secret config)\n *  - a `ctx.web` search/fetch provider (multi-provider pools + fallback) so the\n *    model-facing `web_search`/`web_fetch` tools execute through it\n *  - a fenced `/web-tools/api` route prefix serving the browser settings card\n *    (config authority + credentials state + quota snapshots + test search)\n *\n * @module\n */\nimport type { WebToolsContext } from \"./context-types.ts\";\nimport { Config as PluginConfig, installConfig, type WebToolsSettings } from \"./config.ts\";\nimport { createSearchProvider, createFetchProvider, createPoolStore, PROVIDER_ID, WebToolsWebError } from \"./registry.ts\";\nimport { registerRoutes } from \"./routes.ts\";\nimport { Stats } from \"./stats.ts\";\nimport { CURRENT_VERSION, compareVersions } from \"../shared/version.ts\";\nimport type { VersionCheckView } from \"../shared/api-types.ts\";\nimport { buildPool, selectIndex, markUsed, markUnhealthy, resetHealth } from \"./pool.ts\";\nimport { credRefOf, getProvider, PROVIDER_LIST, quotaOf } from \"./providers/index.ts\";\nimport { seedBraveQuota, setBraveQuotaPersist } from \"./providers/brave.ts\";\nimport { createQuotaPersistScheduler } from \"./quota-persist.ts\";\nimport type { ProviderError } from \"./providers/types.ts\";\nimport { isKeylessSelfHosted } from \"./providers/types.ts\";\nimport type { QuotaSnapshot } from \"./quota.ts\";\nimport { mergePoolQuota } from \"./quota.ts\";\nimport { fetchWithProxy, proxyStatus, proxyFromEnv, proxyFromSystem, getProxyDispatcher } from \"./fetch-proxy.ts\";\nimport { installSearchModeRuntime, SearchModeRuntime, createSearchModeMessages } from \"./search-mode-runtime.ts\";\nimport { createUserMessage } from \"@deepseek-ai/dsh-llm\";\nimport { createProviderHealthStore } from \"./provider-health.ts\";\nimport { transact, setGlobalOutboundAuthorizations, isLocalOrPrivateHost, resolvesToPrivateIp, TransportError, type OutboundAuthorization } from \"./provider-transport.ts\";\nimport {\n  OUTBOUND_AUTHORIZATIONS,\n  buildProviderSnapshot,\n  policyForCustomSource,\n  type ProviderSnapshot,\n} from \"./custom-provider-registry.ts\";\nimport { createCustomAdapter, type CredentialSource, type TransportFn } from \"./providers/custom-compatible.ts\";\nimport {\n  allCredentialRefsOf,\n  credentialRefsOf,\n  loadCustomProviders,\n  validateDraft,\n  validateSourceId,\n  CustomProviderValidationError,\n} from \"./custom-provider-schema.ts\";\nimport type { CustomProviderConfig, CustomSourceErrorCode, CustomSourceTestView, CustomProviderDraft } from \"../shared/custom-provider-types.ts\";\n\nimport { SpecializedSourceRegistry } from \"./sources/registry.ts\";\nimport { XiaohongshuSource } from \"./sources/xiaohongshu.ts\";\nimport { XSource } from \"./sources/x.ts\";\nimport { createNativeBrowserRuntime } from \"./browser/index.ts\";\nimport { extractSearchHints } from \"./search-hints.ts\";\nimport type { SourceFetchOutcome } from \"./sources/types.ts\";\n\n/** Cordis plugin name used by loader diagnostics. */\nexport const name = \"dsh-web-tools\";\n\n/** Services required by this plugin. */\nexport const inject = [\"webServer\", \"settings\", \"credentials\", \"web\", \"agents\", \"commands\"];\n\n/**\n * Plugin-level config: the same schemastery schema as the settings namespace.\n * Cordis requires `Config` to be a schema instance (it calls `.validate` when\n * resolving plugin config); an empty object would crash at load.\n */\nexport const Config = PluginConfig;\n\nconst RELEASES_API = \"https://api.github.com/repos/A3Boy/dsh-web-tools/releases/latest\";\nconst RELEASES_URL = \"https://github.com/A3Boy/dsh-web-tools/releases\";\nconst VERSION_CACHE_MS = 6 * 60 * 60 * 1000;\nlet versionCache: { fetchedAt: number; value: VersionCheckView } | null = null;\n\nexport function toRoutedFetchResponse(url: string, outcome: SourceFetchOutcome) {\n  if (outcome.error) {\n    const error = new WebToolsWebError(\n      `platform fetch failed (${outcome.error.code}): ${outcome.error.message}`,\n    );\n    if (outcome.error.code === \"aborted\") error.code = \"WEB_ABORTED\";\n    throw error;\n  }\n\n  const item = outcome.item;\n  const rawContent = item?.text?.trim();\n  if (!item || !rawContent) {\n    throw new WebToolsWebError(`platform fetch returned empty content for ${url}`);\n  }\n\n  const sections: string[] = [];\n  if (item.title?.trim() && !rawContent.startsWith(item.title.trim())) {\n    sections.push(`# ${item.title.trim()}`);\n  }\n\n  const metadata: string[] = [];\n  const author = item.author?.handle || item.author?.name;\n  if (author) metadata.push(`Author: ${author}`);\n  if (item.publishedAt) metadata.push(`Published: ${item.publishedAt}`);\n  const engagement = [\n    typeof item.likes === \"number\" ? `likes ${item.likes}` : undefined,\n    typeof item.collects === \"number\" ? `collects ${item.collects}` : undefined,\n    typeof item.retweets === \"number\" ? `retweets ${item.retweets}` : undefined,\n    typeof item.replies === \"number\" ? `comments/replies ${item.replies}` : undefined,\n  ].filter(Boolean);\n  if (engagement.length > 0) metadata.push(`Engagement: ${engagement.join(\", \")}`);\n  if (metadata.length > 0) sections.push(metadata.join(\"\\n\"));\n  sections.push(rawContent);\n  if (item.images?.length) sections.push(`Images: ${item.images.length} attached`);\n  const content = sections.join(\"\\n\\n\");\n\n  return {\n    url,\n    statusCode: 200,\n    body: { kind: \"text\" as const, content },\n    truncated: false,\n  };\n}\n\n/** Release lookup is best-effort: startup and settings must work offline. */\nasync function checkVersion(): Promise<VersionCheckView> {\n  if (versionCache && Date.now() - versionCache.fetchedAt < VERSION_CACHE_MS) return versionCache.value;\n\n  const fallback: VersionCheckView = { currentVersion: CURRENT_VERSION, updateAvailable: false };\n  try {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), 5000);\n    timer.unref?.();\n    let response: Response;\n    try {\n      response = await fetchWithProxy(RELEASES_API, {\n        signal: controller.signal,\n        headers: {\n          accept: \"application/vnd.github+json\",\n          \"user-agent\": `dsh-web-tools/${CURRENT_VERSION}`,\n        },\n      });\n    } finally {\n      clearTimeout(timer);\n    }\n\n    // A repository without releases is a valid \"no update\" state.\n    if (response.status === 404) {\n      versionCache = { fetchedAt: Date.now(), value: fallback };\n      return fallback;\n    }\n    if (!response.ok) throw new Error(`GitHub releases returned HTTP ${response.status}`);\n\n    const release = await response.json() as {\n      tag_name?: unknown;\n      name?: unknown;\n      html_url?: unknown;\n      published_at?: unknown;\n      draft?: unknown;\n      prerelease?: unknown;\n    };\n    const latestVersion = typeof release.tag_name === \"string\" ? release.tag_name.replace(/^v/i, \"\") : \"\";\n    if (!latestVersion || release.draft === true || release.prerelease === true) return fallback;\n\n    const value: VersionCheckView = {\n      currentVersion: CURRENT_VERSION,\n      latestVersion,\n      updateAvailable: compareVersions(latestVersion, CURRENT_VERSION) > 0,\n      releaseUrl: typeof release.html_url === \"string\" ? release.html_url : RELEASES_URL,\n      releaseName: typeof release.name === \"string\" && release.name.trim() ? release.name : `v${latestVersion}`,\n      publishedAt: typeof release.published_at === \"string\" ? release.published_at : undefined,\n    };\n    versionCache = { fetchedAt: Date.now(), value };\n    return value;\n  } catch {\n    // Do not cache transient network failures; the next settings open can retry.\n    return fallback;\n  }\n}\n\n/** Resolve one credential ref's state + optional value (Host side only). */\nasync function readCredential(ctx: WebToolsContext, ref: string): Promise<{ configured: boolean; source?: string; writable: boolean; value?: string }> {\n  try {\n    const credentials = ctx.credentials;\n    if (!credentials?.resolve) return { configured: false, writable: true };\n    const resolved = await credentials.resolve(ref);\n    const value = resolved?.value;\n    return {\n      configured: typeof value === \"string\" && value.length > 0,\n      source: resolved?.source,\n      writable: true,\n      ...(typeof value === \"string\" ? { value } : {}),\n    };\n  } catch {\n    return { configured: false, writable: true };\n  }\n}\n\n/**\n * Write a credential value. An empty string UNSETS the credential — the\n * credentials-local provider refuses to store empty values (\"use unset\"),\n * so removing the last key must unset rather than set(\"\").\n */\nasync function writeCredential(ctx: WebToolsContext, ref: string, value: string) {\n  const credentials = ctx.credentials;\n  if (!credentials?.set || !credentials?.unset) throw new Error(\"credentials service unavailable\");\n  if (typeof value === \"string\" && value.length === 0) {\n    await credentials.unset(ref);\n    return;\n  }\n  await credentials.set(ref, value);\n}\n\nexport function apply(ctx: WebToolsContext, config?: unknown) {\n  const stats = new Stats();\n  const configHandle = installConfig(ctx, config);\n  const readConfig = () => configHandle.read();\n\n  /** Coalesced writer for Brave's header-derived, display-only quota cache. */\n  const braveQuotaPersist = createQuotaPersistScheduler((cache) => {\n    void configHandle.write({ braveQuotaCache: cache }).catch(() => {});\n  });\n\n  // ---- ctx.web search + fetch providers ----------------------------------\n  const resolveRuntimeConfig = () => {\n    const cfg = readConfig();\n    return {\n      enabled: cfg.enabled !== false,\n      defaultProvider: cfg.defaultProvider,\n      providerAttemptTimeoutMs: cfg.providerAttemptTimeoutMs,\n      fallbackOrder: cfg.fallbackOrder,\n      searchRoutingPolicy: cfg.searchRoutingPolicy,\n      providerBaseUrls: cfg.providerBaseUrls,\n      enabledProviders: cfg.providerEnabled,\n      providerOptions: cfg.providerOptions,\n    };\n  };\n  const resolveKeys = async (providerName: string) => {\n    // Custom sources own host-derived refs (and may use two refs for Basic).\n    // Resolve through the catalog so both kinds share one pool store, and a\n    // custom source's key can never collide with a built-in's.\n    const entry = buildSnapshot().get(providerName);\n    if (entry && !entry.builtIn) {\n      const refs = entry.refs;\n      if (refs.username !== undefined || refs.password !== undefined) {\n        // Basic auth uses two separate credentials refs so passwords containing\n        // delimiters (comma, semicolon, space) are never corrupted by splitting.\n        // If username is configured, return an account identifier so the pool\n        // allocates a healthy dispatch slot rather than skipping the provider.\n        const user = (await readCredential(ctx, refs.username ?? \"\")).value ?? \"\";\n        return user ? `basic:${user}` : \"\";\n      }\n      if (refs.key === undefined) return \"\";\n      const cred = await readCredential(ctx, refs.key);\n      return cred.value ?? \"\";\n    }\n    const ref = credRefOf(providerName);\n    const cred = await readCredential(ctx, ref);\n    return cred.value ?? \"\";\n  };\n\n  // ---- Issue #9: credentials, secure transport, dynamic catalog -----------\n  /** Credential access by ref, for custom source adapters. */\n  const credentialSource: CredentialSource = {\n    read: async (ref) => (ref ? ((await readCredential(ctx, ref)).value ?? \"\") : \"\"),\n  };\n\n  /** The ambient proxy, if any (env var first, then the Windows system proxy). */\n  const currentProxyUrl = () => proxyFromEnv() ?? proxyFromSystem();\n\n  /** All outbound requests for custom sources go through the guarded transport. */\n  const secureTransport: TransportFn = (request) =>\n    transact(request, {\n      proxyUrl: currentProxyUrl,\n      proxyDispatcher: getProxyDispatcher,\n    });\n\n  /** Credential refs for one source id, resolved against the live catalog. */\n  const buildSnapshot = (): ProviderSnapshot => {\n    const cfg = readConfig();\n    const authorizations = [\n      ...OUTBOUND_AUTHORIZATIONS,\n      ...(Array.isArray(cfg.outboundAuthorizations) ? cfg.outboundAuthorizations : []),\n    ];\n    return buildProviderSnapshot({\n      providerBaseUrls: cfg.providerBaseUrls ?? {},\n      customProviders: loadCustomProviders(cfg.customProviders),\n      credentials: credentialSource,\n      transport: secureTransport,\n      authorizations,\n    });\n  };\n  const resolveSnapshot = () => buildSnapshot();\n  const sourceRefsOf = (sourceId: string): { key?: string; username?: string; password?: string } | undefined =>\n    buildSnapshot().get(sourceId)?.refs;\n\n  // ONE shared pool store for search + fetch: they see the same key usage\n  // and health, and rebuild only when a credential actually changes.\n  const poolStore = createPoolStore(resolveKeys);\n\n  // ONE shared health store so search + fetch respect the same cooldowns.\n  const healthStore = createProviderHealthStore();\n\n  const sourceRegistry = new SpecializedSourceRegistry();\n\n  const generalSearchProvider = createSearchProvider(resolveRuntimeConfig, resolveKeys, {\n    record: (e) => stats.record({ ...e, at: Date.now() }),\n  }, undefined, poolStore, healthStore, resolveSnapshot);\n\n  const generalFetchProvider = createFetchProvider(resolveRuntimeConfig, resolveKeys, undefined, poolStore, healthStore, undefined, resolveSnapshot);\n\n  sourceRegistry.setFallbackProviders(generalSearchProvider, generalFetchProvider);\n\n  // Sync platformEnabled from config on boot and live updates\n  configHandle.onMounted(() => {\n    const cfg = readConfig();\n    if (cfg.platformEnabled) {\n      sourceRegistry.setPlatformEnabled(cfg.platformEnabled);\n    }\n  });\n\n  // Wrap search provider with SpecializedSourceRouter for XHS / X transparent platform handling\n  const routedSearchProvider = {\n    id: PROVIDER_ID,\n    available: () => generalSearchProvider.available(),\n    search: async (request: { query: string; maxResults?: number }, signal?: AbortSignal) => {\n      const outcome = await sourceRegistry.search(\n        request.query,\n        { maxResults: request.maxResults, hints: extractSearchHints(request.query) },\n        signal,\n      );\n      if (outcome.error) {\n        throw new Error(`[${outcome.error.code}] ${outcome.error.message}`);\n      }\n      return {\n        sources: outcome.items.map((item) => ({\n          url: item.url,\n          title: item.title,\n          snippet: item.snippet,\n          publishedAt: item.publishedAt,\n        })),\n        truncated: false,\n      };\n    },\n  };\n  ctx.web.registerSearchProvider(routedSearchProvider as never);\n\n  // Wrap fetch provider with SpecializedSourceRouter\n  const routedFetchProvider = {\n    id: `${PROVIDER_ID}-fetch`,\n    available: () => generalFetchProvider.available(),\n    fetch: async (request: { url: string }, signal?: AbortSignal) => {\n      const outcome = await sourceRegistry.fetch(request.url, signal);\n      return toRoutedFetchResponse(request.url, outcome);\n    },\n  };\n  ctx.web.registerFetchProvider(routedFetchProvider as never);\n\n  // Specialized Sources: Register Xiaohongshu and Twitter/X with NativeBrowserRuntime\n  const nativeRuntime = createNativeBrowserRuntime();\n  const xhsSource = new XiaohongshuSource(nativeRuntime);\n  const xSource = new XSource(nativeRuntime);\n  sourceRegistry.registerSource(xhsSource);\n  sourceRegistry.registerSource(xSource);\n\n  // Hook NativeBrowserRuntime lifecycle into Cordis effect\n  ctx.effect(\n    () => {\n      return () => {\n        nativeRuntime.dispose().catch(() => {});\n      };\n    },\n    \"dsh-web-tools: native browser runtime\",\n  );\n\n  /** Run one real minimal search through a single provider (test connection). */\n  async function testProviderSearch(providerName: string, query: string) {\n    const adapter = getProvider(providerName);\n    const started = Date.now();\n    try {\n      // Keyless self-hosted providers (SearXNG) work without any key.\n      let key = \"\";\n      if (!isKeylessSelfHosted(adapter)) {\n        // Use the SHARED pool store so a failed probe marks the tested key\n        // unhealthy — the card's per-key health must reflect reality, not a\n        // fresh pool where every key always looks healthy.\n        const entries = await poolStore.poolOf(providerName);\n        if (entries.length === 0) throw Object.assign(new Error(\"no API key configured\"), { code: \"config\" });\n        if (!entries.some((e) => e.healthy)) resetHealth(entries);\n        const index = selectIndex(entries);\n        const entry = entries[index];\n        key = (entry?.key ?? \"\").trim();\n        try {\n          const outcome = await adapter.search(query, 1, key, readConfig().providerBaseUrls[providerName]);\n          markUsed(entries, index);\n          if (!entry.healthy) entry.healthy = true;\n          const latencyMs = Date.now() - started;\n          return {\n            ok: true,\n            latencyMs,\n            resultCount: outcome.sources.length,\n            title: outcome.sources[0]?.title,\n          };\n        } catch (e) {\n          // Same policy as the executor: only an auth failure indicts the key.\n          const err = toProviderError(e);\n          if (err.code === \"auth\") markUnhealthy(entries, index);\n          throw err;\n        }\n      }\n      const outcome = await adapter.search(query, 1, key, readConfig().providerBaseUrls[providerName]);\n      const latencyMs = Date.now() - started;\n      return {\n        ok: true,\n        latencyMs,\n        resultCount: outcome.sources.length,\n        title: outcome.sources[0]?.title,\n      };\n    } catch (e) {\n      const err = toProviderError(e);\n      return { ok: false, error: { code: err.code, message: err.message } };\n    }\n  }\n\n  /** Run the REAL search path (default provider + fallback) for the card.\n   *  Delegates to the same provider used by agent web_search, so Test Search\n   *  never drifts from production behavior. */\n  /** Run the REAL search path (default provider + fallback) for the card.\n   *  Delegates to the same provider used by agent web_search, so Test Search\n   *  never drifts from production behavior. Total latency measured here. */\n  async function testFullSearch(query: string) {\n    const started = Date.now();\n    try {\n      const result = await routedSearchProvider.search(\n        { query, maxResults: 5 },\n        undefined, // no caller signal for a manual card test\n      );\n      return {\n        ok: true,\n        backend: (result as unknown as { backend?: string }).backend,\n        latencyMs: Date.now() - started,\n        resultCount: result.sources.length,\n        results: result.sources.slice(0, 5).map((s: any) => ({ title: s.title ?? s.url, url: s.url, snippet: s.snippet ?? \"\" })),\n        attempts: (result as unknown as { attempts?: Array<{ provider: string; outcome: string; latencyMs?: number }> }).attempts,\n      };\n    } catch (e) {\n      const err = toProviderError(e);\n      return {\n        ok: false,\n        latencyMs: Date.now() - started,\n        error: { code: err.code, message: err.message },\n      };\n    }\n  }\n\n  /** Quota cache: { fetchedAt, per provider snapshot }. */\n  let quotaCache: { fetchedAt: number; quotas: Record<string, QuotaSnapshot> } | null = null;\n  const QUOTA_CACHE_MS = 5 * 60 * 1000; // 5 min — quota is display-only, no 30s polling\n  const QUOTA_TIMEOUT_MS = 8000;\n\n  async function describeQuotas(force = false): Promise<Record<string, QuotaSnapshot>> {\n    if (!force && quotaCache && Date.now() - quotaCache.fetchedAt < QUOTA_CACHE_MS) return quotaCache.quotas;\n\n    const cfg = readConfig();\n    const chainNames = new Set<string>([cfg.defaultProvider, ...cfg.fallbackOrder]);\n    const summary = stats.summary();\n\n    // Read all credentials in parallel ONCE\n    const credentialEntries = await Promise.all(\n      PROVIDER_LIST.map(async (meta) => {\n        const ref = credRefOf(meta.name);\n        const cred = await readCredential(ctx, ref);\n        return { meta, ref, cred };\n      }),\n    );\n\n    const wanted = new Set<string>(chainNames);\n    for (const { meta, cred } of credentialEntries) {\n      if ((cred.value ?? \"\").trim().length > 0) wanted.add(meta.name);\n    }\n\n    const credMap = new Map(credentialEntries.map((e) => [e.meta.name, e.cred]));\n\n    // Parallel, timeout-bounded, only providers that can report quota.\n    const results = await Promise.allSettled(\n      PROVIDER_LIST.filter((meta) => wanted.has(meta.name)).map(async (meta): Promise<[string, QuotaSnapshot]> => {\n        const cred = credMap.get(meta.name);\n        const localSearches = summary.byProvider[meta.name]?.success ?? 0;\n        // Multi-key pool: query EVERY key and merge — the card shows the\n        // TOTAL pool balance, not one key's. Each key is authenticated\n        // separately (never join the raw string).\n        const keys = buildPool(cred?.value ?? \"\").map((e) => e.key);\n        if (keys.length === 0) {\n          const snapshot = await withTimeoutMs(\n            quotaOf(meta.name, \"\", cfg.providerBaseUrls[meta.name], localSearches),\n            QUOTA_TIMEOUT_MS,\n          );\n          return [meta.name, snapshot];\n        }\n        const perKey = await Promise.allSettled(\n          keys.map((k) =>\n            withTimeoutMs(quotaOf(meta.name, k, cfg.providerBaseUrls[meta.name], localSearches), QUOTA_TIMEOUT_MS),\n          ),\n        );\n        const fulfilled = perKey.filter((p): p is PromiseFulfilledResult<QuotaSnapshot> => p.status === \"fulfilled\").map((p) => p.value);\n        if (fulfilled.length === 0) {\n          const first = perKey.find((p): p is PromiseRejectedResult => p.status === \"rejected\");\n          throw Object.assign(new Error(`quota check failed: ${first?.reason instanceof Error ? first.reason.message : String(first?.reason)}`), {\n            provider: meta.name,\n          });\n        }\n        return [meta.name, mergePoolQuota(fulfilled)];\n      }),\n    );\n\n    const quotas: Record<string, QuotaSnapshot> = {};\n    for (const r of results) {\n      if (r.status === \"fulfilled\") {\n        const [name, snap] = r.value;\n        quotas[name] = snap;\n      } else {\n        const name = (r.reason as { provider?: string })?.provider ?? \"unknown\";\n        quotas[name] = {\n          supported: false,\n          authoritative: false,\n          unit: \"unknown\",\n          source: \"dashboard\",\n          fetchedAt: Date.now(),\n          note: `Quota check failed: ${r.reason instanceof Error ? r.reason.message : String(r.reason)}`,\n        };\n      }\n    }\n\n    quotaCache = { fetchedAt: Date.now(), quotas };\n    return quotas;\n  }\n\n  // ---- Brave quota persistence --------------------------------------------\n  // Brave has no quota endpoint; its only quota signal is the X-RateLimit-*\n  // header captured during a real search. Persist those snapshots into the\n  // settings namespace so a restart does not forget the last known balance.\n  // Seeding MUST wait for the settings namespace (ctx.inject is async) — in\n  // the synchronous apply() body readConfig() would only return defaults.\n  configHandle.onMounted(() => {\n    const cfg = readConfig();\n    syncGlobalOutboundAuthorizations();\n    const braveCache = cfg.braveQuotaCache ?? {};\n    braveQuotaPersist.seed(braveCache);\n    for (const [key, snap] of Object.entries(braveCache)) {\n      if (key && snap && typeof snap === \"object\") seedBraveQuota(key, snap as QuotaSnapshot);\n    }\n  });\n  // Coalesced: a settings write costs ~2.5s on DSH 0.1.7 (profile patch +\n  // Loader reconciliation under hmr.runExclusive), and Brave reports quota in\n  // search headers, so writing through per search would run that path for a\n  // value the card only displays.\n  setBraveQuotaPersist((apiKey, snapshot) => braveQuotaPersist.record(apiKey, snapshot));\n  ctx.effect(\n    () => () => braveQuotaPersist.dispose(),\n    \"dsh-web-tools: brave quota persistence\",\n  );\n\n  // ---- Search Mode (per-session \"required web search\" turn policy) ---------\n  // Host-owned state riding the provider seam: `available()` means the search\n  // provider service is enabled with a chain provider. Messages use the\n  // OFFICIAL @deepseek-ai/dsh-llm createUserMessage ({ content, source }):\n  // required = durable snapshot section, correction = one-shot notice.\n  const searchModeMessages = createSearchModeMessages(\n    (input) => createUserMessage(input as never),\n    () => {\n      // The platform-routing lines only make sense while a platform source can\n      // actually serve a routed query; otherwise the model is taught a prefix\n      // that silently does nothing.\n      const cfg = readConfig();\n      const platforms = cfg.platformEnabled ?? {};\n      return platforms.xiaohongshu !== false || platforms.x !== false;\n    },\n  );\n  const searchModeRuntime = new SearchModeRuntime(() => routedSearchProvider.available());\n  ctx.effect(\n    () =>\n      installSearchModeRuntime(\n        ctx,\n        { searchAvailable: () => routedSearchProvider.available() },\n        searchModeRuntime,\n        searchModeMessages,\n      ),\n    \"dsh-web-tools: search-mode runtime\",\n  );\n\n  // The routes expose the same runtime map to the button / slash commands.\n  const searchMode = {\n    view: (sessionId: string) => searchModeRuntime.view(sessionId),\n    set: (sessionId: string, mode: \"auto\" | \"required\" | \"off\") => {\n      searchModeRuntime.setMode(sessionId, mode);\n      return searchModeRuntime.view(sessionId);\n    },\n  };\n\n  // ---- Issue #9: custom source lifecycle helpers --------------------------\n  /**\n   * Publish operator outbound-authorization entries into the shared network\n   * gate. Called on boot and after every config write, so authorization edits\n   * apply live.\n   */\n  function syncGlobalOutboundAuthorizations() {\n    const cfg = readConfig();\n    setGlobalOutboundAuthorizations(Array.isArray(cfg.outboundAuthorizations) ? cfg.outboundAuthorizations : []);\n  }\n\n  /**\n   * Drop runtime state for ONE source.\n   *\n   * Scoped to a single source on purpose: clearing every cooldown on an edit\n   * would discard still-valid state for unrelated sources (an unrelated\n   * provider's active 429 backoff would be forgotten and re-hit immediately).\n   */\n  function forgetSource(sourceId: string) {\n    healthStore.deleteCooldown(sourceId);\n    poolStore.forget(sourceId);\n  }\n\n  /** Remove every credential ref a deleted source owned. */\n  async function revokeSourceCredentials(sourceId: string): Promise<{ removed: string[]; failed: string[] }> {\n    const removed: string[] = [];\n    const failed: string[] = [];\n    for (const ref of allCredentialRefsOf(sourceId)) {\n      try {\n        const cred = await readCredential(ctx, ref);\n        if (!cred.configured) continue;\n        await writeCredential(ctx, ref, \"\");\n        removed.push(ref);\n      } catch {\n        failed.push(ref);\n      }\n    }\n    return { removed, failed };\n  }\n\n  /**\n   * Run a bounded search through a custom source WITHOUT touching live state.\n   *\n   * Used by `sources/test` for both saved sources and unsaved drafts. It never\n   * consults or mutates the shared pool or health store, so a failed probe of a\n   * draft cannot mark a real provider's key unhealthy or start a cooldown.\n   */\n  async function testSource(input: {\n    draft?: unknown;\n    sourceId?: string;\n    credential?: {\n      mode?: \"stored\" | \"candidate\";\n      value?: string;\n      username?: string;\n      password?: string;\n    };\n    confirmTarget?: boolean;\n    query: string;\n  }): Promise<CustomSourceTestView> {\n    const TEST_TIMEOUT_MS = 15_000;\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(new Error(\"test timed out\")), TEST_TIMEOUT_MS);\n    timer.unref?.();\n\n    try {\n      let config: CustomProviderConfig;\n      if (input.draft !== undefined && input.draft !== null) {\n        // If a draft is supplied, always test the current draft configuration.\n        // If an existing sourceId is also present, retain that sourceId.\n        const draft: CustomProviderDraft = validateDraft(input.draft);\n        const id = input.sourceId ?? `custom_${\"0\".repeat(16)}`;\n        config = { schemaVersion: 1, id, revision: 1, ...draft };\n      } else if (input.sourceId !== undefined) {\n        const sourceId = validateSourceId(input.sourceId);\n        const stored = loadCustomProviders(readConfig().customProviders).find((entry) => entry.id === sourceId);\n        if (!stored) return { ok: false, error: { code: \"not-found\", message: `Unknown custom source \"${sourceId}\"` } };\n        config = stored;\n      } else {\n        return { ok: false, error: { code: \"config\", message: \"draft or sourceId required\" } };\n      }\n\n      const refs = credentialRefsOf(config.id, config.auth.mode);\n      const credInput = input.credential;\n\n      const credential: CredentialSource = {\n        read: async (ref) => {\n          if (credInput?.mode === \"candidate\") {\n            if (ref === refs.key && typeof credInput.value === \"string\") return credInput.value;\n            if (ref === refs.username && typeof credInput.username === \"string\") return credInput.username;\n            if (ref === refs.password && typeof credInput.password === \"string\") return credInput.password;\n          }\n          // Stored mode or fallback:\n          if (input.sourceId !== undefined) {\n            return credentialSource.read(ref);\n          }\n          if (ref === refs.key && typeof credInput?.value === \"string\") return credInput.value;\n          if (ref === refs.username && typeof credInput?.username === \"string\") return credInput.username;\n          if (ref === refs.password && typeof credInput?.password === \"string\") return credInput.password;\n          return \"\";\n        },\n      };\n\n      const cfg = readConfig();\n      const existingAuths = [\n        ...OUTBOUND_AUTHORIZATIONS,\n        ...(Array.isArray(cfg.outboundAuthorizations) ? cfg.outboundAuthorizations : []),\n      ];\n      const endpointUrl = new URL(config.endpoint.baseUrl);\n      const endpointPort = endpointUrl.port\n        ? Number(endpointUrl.port)\n        : (endpointUrl.protocol === \"https:\" ? 443 : 80);\n      const isPrivateOrLoopback =\n        isLocalOrPrivateHost(endpointUrl.hostname) ||\n        (await resolvesToPrivateIp(endpointUrl.hostname));\n      const isHttp = endpointUrl.protocol === \"http:\";\n\n      const isAlreadyAuthorized = existingAuths.some(\n        (a) =>\n          (a.host.toLowerCase() === endpointUrl.hostname.toLowerCase() ||\n            (a.host.startsWith(\".\") && endpointUrl.hostname.toLowerCase().endsWith(a.host.toLowerCase()))) &&\n          (a.port === undefined || a.port === endpointPort) &&\n          (!isPrivateOrLoopback || a.allowPrivate) &&\n          (!isHttp || a.allowHttp),\n      );\n\n      const candidateAuth: OutboundAuthorization[] = [];\n      if ((isPrivateOrLoopback || isHttp) && !isAlreadyAuthorized) {\n        if (input.confirmTarget !== true) {\n          const targetStr = `${endpointUrl.hostname}:${endpointPort}`;\n          return {\n            ok: false,\n            error: {\n              code: \"conflict\",\n              message: `此搜索服务位于本地网络或使用未加密 HTTP 连接。是否允许访问 ${targetStr}？若配置了 API Key，对应凭证将发送给该服务。`,\n            },\n          };\n        }\n        candidateAuth.push({\n          host: endpointUrl.hostname,\n          port: endpointPort,\n          allowPrivate: isPrivateOrLoopback,\n          allowHttp: isHttp,\n          allowProxy: !isPrivateOrLoopback,\n          sourceId: input.sourceId,\n          managedBy: \"custom-source\",\n          note: `Operator-confirmed: ${config.name}`,\n        });\n      }\n\n      const authorizations = [...existingAuths, ...candidateAuth];\n      const { policy, trust } = policyForCustomSource(config, authorizations);\n      const adapter = createCustomAdapter(config, {\n        transport: secureTransport,\n        credentials: credential,\n        refs,\n        policy,\n        trust,\n      });\n\n      const started = Date.now();\n      try {\n        const outcome = await adapter.search(input.query, 3, \"\", undefined, { signal: controller.signal });\n        return {\n          ok: true,\n          status: \"connected\",\n          latencyMs: Date.now() - started,\n          resultCount: outcome.sources.length,\n          results: outcome.sources.slice(0, 3).map((s) => ({\n            title: s.title ?? s.url,\n            url: s.url,\n            ...(s.snippet ? { snippet: s.snippet } : {}),\n          })),\n        };\n      } catch (err) {\n        if (\n          err instanceof TransportError &&\n          err.code === \"destination-blocked\" &&\n          err.message.includes(\"private, loopback, or link-local\") &&\n          input.confirmTarget !== true\n        ) {\n          const targetStr = `${endpointUrl.hostname}:${endpointPort}`;\n          return {\n            ok: false,\n            latencyMs: Date.now() - started,\n            error: {\n              code: \"conflict\",\n              message: `此搜索服务位于本地网络或解析到内网私有地址。是否允许访问 ${targetStr}？若配置了 API Key，对应凭证将发送给该服务。`,\n            },\n          };\n        }\n        const classified = toProviderError(err);\n        return {\n          ok: false,\n          latencyMs: Date.now() - started,\n          error: {\n            code: mapProviderErrorToSourceCode(classified.code),\n            // The message is built by our own adapters from a label + status;\n            // upstream response bodies, headers and credentials are never\n            // included, so nothing sensitive can reach the browser here.\n            message: classified.message,\n          },\n        };\n      }\n    } catch (err) {\n      if (err instanceof CustomProviderValidationError) {\n        return { ok: false, error: { code: \"config\", message: err.message } };\n      }\n      return {\n        ok: false,\n        error: { code: \"config\", message: err instanceof Error ? err.message : String(err) },\n      };\n    } finally {\n      clearTimeout(timer);\n    }\n  }\n\n  // ---- fenced HTTP routes for the card ------------------------------------\n  ctx.effect(\n    () =>\n      registerRoutes(ctx, {\n        readConfig: () => readConfig() as unknown as Record<string, unknown>,\n        writeConfig: async (patch) => {\n          await configHandle.write(patch as Partial<WebToolsSettings>);\n          // Publish the (possibly updated) operator outbound-authorization list\n          // to the shared network gate immediately, so a just-saved intranet\n          // gateway starts working without a plugin reload.\n          syncGlobalOutboundAuthorizations();\n        },\n        readCredential: (ref) => readCredential(ctx, ref),\n        writeCredential: (ref, value) => writeCredential(ctx, ref, value),\n        testProviderSearch,\n        testFullSearch,\n        describeQuotas,\n        nativeRuntime,\n        sourceRegistry,\n        checkVersion,\n        poolEntries: (providerName) => poolStore.poolOf(providerName),\n        proxyStatus,\n        searchMode,\n        sourceRefs: sourceRefsOf,\n        testSource,\n        revokeSourceCredentials: (sourceId) => revokeSourceCredentials(sourceId),\n        forgetSource: (sourceId) => forgetSource(sourceId),\n      }),\n    \"dsh-web-tools: /web-tools/api routes\",\n  );\n}\n\n/**\n * Translate the executor's error vocabulary into the stable, UI-facing source\n * codes the editor switches on. Kept as an explicit mapping so adding a new\n * provider code forces a decision here instead of silently becoming \"network\".\n */\nfunction mapProviderErrorToSourceCode(code: ProviderError[\"code\"]): CustomSourceErrorCode {\n  switch (code) {\n    case \"auth\":\n      return \"auth\";\n    case \"timeout\":\n      return \"timeout\";\n    case \"invalid-response\":\n      return \"invalid-response\";\n    case \"config\":\n      return \"config\";\n    case \"bad-request\":\n      return \"invalid-url\";\n    case \"aborted\":\n      return \"timeout\";\n    default:\n      return \"network\";\n  }\n}\n\nfunction toProviderError(error: unknown): ProviderError {\n  if (typeof error === \"object\" && error !== null && \"code\" in error && typeof (error as ProviderError).code === \"string\") {\n    return error as ProviderError;\n  }\n  const message = describeFetchError(error);\n  const err = new Error(message) as ProviderError;\n  err.code = \"network\";\n  return err;\n}\n\n/**\n * Human-readable network failure. undici's global fetch throws a generic\n * `TypeError: fetch failed` whose real cause (ECONNREFUSED, DNS, TLS,\n * timeout, proxy refusal) sits in `error.cause` — surface it so the settings\n * card shows why a provider is unreachable instead of the bare wrapper.\n */\nfunction describeFetchError(error: unknown): string {\n  const top = error instanceof Error ? error.message : String(error);\n  let cause: unknown = (error as { cause?: unknown })?.cause;\n  const seen = new Set<unknown>([error]);\n  while (cause !== undefined && cause !== null && !seen.has(cause)) {\n    seen.add(cause);\n    if (cause instanceof AggregateError) {\n      const first = cause.errors?.[0];\n      if (first instanceof Error && first.message && !seen.has(first)) {\n        cause = first;\n        continue;\n      }\n    }\n    const msg = cause instanceof Error ? cause.message : String(cause);\n    if (msg && msg !== top) return `${top}: ${msg}`;\n    cause = (cause as { cause?: unknown })?.cause;\n  }\n  return top;\n}\n\n/** Simple timeout wrapper for side-channel quota lookups (no abort needed). */\nfunction withTimeoutMs<T>(promise: Promise<T>, ms: number): Promise<T> {\n  return Promise.race([\n    promise,\n    new Promise<never>((_, reject) => {\n      const timer = setTimeout(() => reject(new Error(`timed out after ${ms}ms`)), ms);\n      // Never keep the process alive just for an expired quota timer.\n      timer.unref?.();\n    }),\n  ]);\n}\n\nexport { PROVIDER_ID };\n"
    },
    {
      "path": "src/client/index.ts",
      "content": "/**\n * dsh-web-tools — browser client plugin entry.\n *\n * Registers a top-level Settings page (`settings.section`, id `web-tools`)\n * — the same slot contract the official Models / Plugins pages use — so the\n * plugin appears in the Settings nav as \"Web Search / 网页搜索\", not buried\n * under Plugins → Plugin configuration.\n *\n * The page talks to the Host exclusively through the plugin's fenced\n * `/web-tools/api` HTTP routes (see ../host/routes.ts) — credentials never\n * reach the browser.\n *\n * Copy is registered through the DSH locale service (zh/en dictionaries\n * in ./i18n-dict.ts). The page follows the DSH UI language by default, and additionally\n * offers its own language selector (Follow system / 中文 / English) that is\n * persisted in the plugin's own config — it never changes the DSH-wide\n * language.\n * @module\n */\nimport { WebToolsSection } from \"./WebToolsSection.tsx\";\nimport { registerSettingsSection, type UiFace } from \"./registration.ts\";\nimport { SearchModeButton } from \"./SearchModeButton.tsx\";\nimport { zhDict, enDict } from \"./i18n-dict.ts\";\nimport { adoptWebToolsStyles } from \"./ui/styles.ts\";\nimport * as React from \"react\";\nimport { useSyncExternalStore } from \"react\";\n\nexport { zhDict, enDict };\n\n/** Locale namespace for this page's copy. */\nexport const NS = \"dsh-web-tools\";\n\n/** Services required by this client plugin. */\nexport const inject = [\"slots\", \"locale\"];\n\n/** Register the Settings page. */\nclass SectionErrorBoundary extends React.Component<{ children: React.ReactNode }, { error: Error | null }> {\n  state: { error: Error | null } = { error: null };\n  static getDerivedStateFromError(error: Error) {\n    return { error };\n  }\n  componentDidCatch(error: Error, info: React.ErrorInfo) {\n    console.error(\"[dsh-web-tools] WebToolsSection render error\", error, info);\n  }\n  render() {\n    if (this.state.error !== null) {\n      return React.createElement(\n        \"div\",\n        { style: { padding: 12, color: \"#e5484d\", fontFamily: \"ui-monospace, monospace\", fontSize: 12, whiteSpace: \"pre-wrap\", lineHeight: 1.5 } },\n        \"[dsh-web-tools] 页面渲染失败:\\n\" + (this.state.error.stack ?? String(this.state.error)),\n      );\n    }\n    return this.props.children;\n  }\n}\n\nfunction SectionWithBoundary(props: Record<string, unknown>) {\n  return React.createElement(SectionErrorBoundary, null, React.createElement(WebToolsSection, props as never));\n}\n\nexport function apply(ctx: any) {\n  adoptWebToolsStyles();\n\n  ctx.effect(() =>\n    ctx.locale.register(NS, {\n      zh: zhDict,\n      en: enDict,\n    }),\n  );\n\n  const t = ctx.locale.bind(NS);\n\n  const ui: UiFace = {\n    getActiveLocale: () => ctx.locale.getLocale().active,\n    subscribeLocale: (fn) => ctx.locale.subscribe(fn),\n    zhDict,\n    enDict,\n  };\n\n  registerSettingsSection(ctx, t, SectionWithBoundary, ui);\n\n  // \"联网搜索\" per-session toggle — a small always-visible control at the left\n  // end of the composer tool row (official `conversation.input.left` seat).\n  // Session-scoped: the seat supplies `sessionId` as a standard prop. Because\n  // this slot exposes no `inject`, a thin wrapper forwards the sessionId along\n  // with locale-localized copy (re-renders when the page language flips).\n  const SearchModeControl = (props: { sessionId: string }) => {\n    useSyncExternalStore(\n      (cb) => ctx.locale.subscribe(cb),\n      () => ctx.locale.getLocale().active,\n    );\n    return React.createElement(SearchModeButton, {\n      sessionId: props.sessionId,\n      unavailableLabel: t(\"searchModeUnavailable\"),\n      menuLabel: t(\"searchModeMenuLabel\"),\n      labels: {\n        auto: t(\"searchModeAuto\"),\n        required: t(\"searchModeRequired\"),\n        off: t(\"searchModeOff\"),\n      },\n      descriptions: {\n        auto: t(\"searchModeAutoDesc\"),\n        required: t(\"searchModeRequiredDesc\"),\n        off: t(\"searchModeOffDesc\"),\n      },\n    });\n  };\n\n  ctx.slots.inject(\"conversation.input.left\", () =>\n    ctx.slots.register(\n      {\n        name: \"conversation.input.left\",\n        id: \"dsh-web-tools-search-mode\",\n        order: 30,\n        // Localized projected label follows the active locale without re-register.\n        label: () => t(\"searchModeLabel\"),\n      },\n      SearchModeControl,\n    ),\n  );\n}\n"
    },
    {
      "path": "src/host/registry.ts",
      "content": "/**\n * dsh-web-tools — search executor: account pools + deterministic fallback.\n *\n * Implements the DSH `WebSearchProvider` contract (`id`, `available()`,\n * `search(request, signal)`) registered on `ctx.web`. The seam's model-facing\n * `web_search`/`web_fetch` tools (from `dsh-tool-web`) execute through this.\n * The provider contracts are restated structurally (no dsh-web import) so the\n * plugin resolves outside the monorepo, following the better-sidebar pattern.\n * @module\n */\nimport { classifyFailure, fallbackChain } from \"./fallback.ts\";\nimport { resolveSearchChain, type SearchRoutingPolicy, type SearchRoutingState } from \"./routing-policy.ts\";\nimport { buildPool, markUnhealthy, markUsed, reserveKey, releaseKey, selectIndex, PoolEntry } from \"./pool.ts\";\nimport { PROVIDERS } from \"./providers/index.ts\";\nimport type { ProviderError, ProviderErrorCode } from \"./providers/types.ts\";\nimport { isKeylessSelfHosted } from \"./providers/types.ts\";\nimport type { StoredProviderOptions } from \"../shared/provider-options.ts\";\nimport { extractSearchHints } from \"./search-hints.ts\";\nimport type { ProviderHealthStore } from \"./provider-health.ts\";\nimport { fetchGenericWebPage, GenericFetchError } from \"./generic-fetch.ts\";\nimport type { CatalogEntry, ProviderSnapshot } from \"./custom-provider-registry.ts\";\n\n/** Stable provider id registered on ctx.web (the `web` row's searchProvider). */\nexport const PROVIDER_ID = \"dsh-web-tools\";\n\n/** Structural mirror of the seam's WebSearchProvider contract. */\nexport interface WebSearchProviderLike {\n  id: string;\n  available(): boolean;\n  search(request: { query: string; maxResults?: number }, signal?: AbortSignal): Promise<{\n    content?: string;\n    sources: Array<{ url: string; title?: string; snippet?: string; publishedAt?: string }>;\n    truncated: boolean;\n  }>;\n}\n\n/** Structural mirror of the seam's WebFetchProvider contract. */\nexport interface WebFetchProviderLike {\n  id: string;\n  available(): boolean;\n  fetch(request: { url: string }, signal?: AbortSignal): Promise<{\n    url: string;\n    statusCode: number;\n    body: { kind: \"html\" | \"text\"; content: string };\n    truncated: boolean;\n    backend?: string;\n    metadata?: {\n      title?: string;\n      author?: string;\n      publishedAt?: string;\n      description?: string;\n    };\n  }>;\n}\n\n/** A classified failure the executor throws (WebError-compatible shape). */\nexport class WebToolsWebError extends Error {\n  code = \"WEB_PROVIDER_ERROR\";\n  attempts?: Array<{ provider: string; outcome: string; latencyMs?: number }>;\n}\n\n/** Runtime configuration resolved per search (snapshot per operation). */\nexport interface WebToolsRuntimeConfig {\n  enabled: boolean;\n  defaultProvider: string;\n  /** Per-attempt budget for ONE provider call (the DSH tool owns the overall timeout). */\n  providerAttemptTimeoutMs: number;\n  fallbackOrder: string[];\n  /** Search routing policy — how the runtime picks the starting provider per query. */\n  searchRoutingPolicy?: SearchRoutingPolicy;\n  providerBaseUrls: Record<string, string>;\n  enabledProviders: Record<string, boolean>;\n  providerOptions?: StoredProviderOptions;\n}\n\n/** Live per-provider key pools, keyed by provider name. */\nexport type Pools = Record<string, PoolEntry[]>;\n\n/** A per-provider pool with the raw credential it was built from. */\ninterface PoolSlot {\n  raw: string;\n  entries: PoolEntry[];\n}\n\n/**\n * Shared credential pool store. One instance per plugin; Search and Fetch\n * executors share it so they never fight over separate pools.\n *\n * - Rebuilds a provider's pool ONLY when its credential string changed\n *   (avoids the concurrent-search race of replacing entries out from under an\n *   in-flight request).\n * - Preserves uses/health for keys that persist across rebuilds.\n * - markUsed/markUnhealthy mutate the stable entries array in place.\n */\nexport function createPoolStore(resolveKeys: (providerName: string) => Promise<string>) {\n  const slots = new Map<string, PoolSlot>();\n\n  async function poolOf(providerName: string): Promise<PoolEntry[]> {\n    const raw = await resolveKeys(providerName);\n    const prev = slots.get(providerName);\n    if (prev && prev.raw === raw) return prev.entries;\n\n    const next = buildPool(raw);\n    if (prev) {\n      const byKey = new Map(prev.entries.map((e) => [e.key, e]));\n      for (const e of next) {\n        const old = byKey.get(e.key);\n        if (old) {\n          e.uses = old.uses;\n          e.healthy = old.healthy;\n        }\n      }\n    }\n    slots.set(providerName, { raw, entries: next });\n    return next;\n  }\n\n  /**\n   * Drop one source's pool entirely.\n   *\n   * Used when a source is deleted or its credential/endpoint identity changes:\n   * the cached entries (and any per-key health they carry) no longer describe\n   * anything real. Other sources' pools are untouched.\n   */\n  function forget(providerName: string): void {\n    slots.delete(providerName);\n  }\n\n  return { poolOf, forget };\n}\n\nexport type PoolStore = ReturnType<typeof createPoolStore>;\n\n/** Structural subset of a provider adapter the executor needs (injectable). */\nexport interface ProviderAdapterLike {\n  name: string;\n  needsBaseUrl: boolean;\n  fetchCapable: boolean;\n  search(query: string, maxResults: number | undefined, apiKey: string, baseUrl: string | undefined, contextOrSignal?: AbortSignal | { signal?: AbortSignal; options?: unknown; hints?: unknown }): Promise<{ sources: Array<{ url: string; title?: string; snippet?: string; publishedAt?: string }> }>;\n  fetch(url: string, apiKey: string, baseUrl: string | undefined, contextOrSignal?: AbortSignal | { signal?: AbortSignal; options?: unknown; hints?: unknown }): Promise<{ text: string }>;\n}\n\n/** Build a WebToolsSearchProvider for `ctx.web.registerSearchProvider`.\n *  `adapterRegistry` is injectable for tests; production uses the global\n *  PROVIDERS map (passed by index.ts via the default).\n *\n *  `resolveSnapshot` is the Issue #9 seam: when supplied, EVERY request reads\n *  one immutable catalog snapshot up front and takes adapters, credentials,\n *  endpoint overrides and keyless-ness from it. A config edit mid-flight can\n *  therefore never swap an adapter out from under the request. */\nexport function createSearchProvider(\n  resolveConfig: () => WebToolsRuntimeConfig,\n  resolveKeys: (providerName: string) => Promise<string>,\n  stats: {\n    record: (entry: { provider: string; outcome: string; latencyMs: number }) => void;\n  },\n  adapterRegistry: Record<string, ProviderAdapterLike> = PROVIDERS,\n  poolStore?: PoolStore,\n  healthStore?: ProviderHealthStore,\n  resolveSnapshot?: () => ProviderSnapshot,\n): WebSearchProviderLike {\n  const pools = poolStore ?? createPoolStore(resolveKeys);\n  const routingState: SearchRoutingState = { nextRoundRobinIndex: 0 };\n\n  /** Adapter for one source id, preferring the live snapshot. */\n  const adapterFor = (sourceId: string, snapshot?: ProviderSnapshot): ProviderAdapterLike | undefined => {\n    if (snapshot) return snapshot.get(sourceId)?.adapter as ProviderAdapterLike | undefined;\n    return adapterRegistry[sourceId];\n  };\n\n  /** Whether one source can run without a credential. */\n  const keylessOf = (sourceId: string, adapter: ProviderAdapterLike, snapshot?: ProviderSnapshot): boolean => {\n    const entry = snapshot?.get(sourceId);\n    if (entry) return entry.keyless;\n    return isKeylessSelfHosted(adapter);\n  };\n\n  return {\n    id: PROVIDER_ID,\n\n    /**\n     * \"Web Search provider service available\": the plugin is enabled AND the\n     * configured chain contains at least one enabled adapter. This deliberately\n     * does NOT check that an API key is configured — keys are resolved lazily\n     * per search and a missing key surfaces as an auth failure at call time.\n     * UI copy treats this as \"service available\" (a chain provider exists), not\n     * \"a credential is ready\"; per-key readiness is shown in the settings card.\n     */\n    available() {\n      const cfg = resolveConfig();\n      if (!cfg.enabled) return false;\n      const snapshot = resolveSnapshot?.();\n      const baseChain = fallbackChain({\n        defaultProvider: cfg.defaultProvider,\n        fallbackOrder: cfg.fallbackOrder,\n      });\n      const chain = resolveSearchChain(\n        baseChain,\n        cfg.searchRoutingPolicy ?? \"ordered\",\n      );\n      return chain.some((name) => {\n        if (cfg.enabledProviders[name] === false) return false;\n        const entry = snapshot?.get(name);\n        if (entry?.config && entry.config.enabled === false) return false;\n        return adapterFor(name, snapshot) !== undefined;\n      });\n    },\n\n    async search(request: { query: string; maxResults?: number }, signal?: AbortSignal) {\n      const cfg = resolveConfig();\n      if (!cfg.enabled) throw new WebToolsWebError(\"web search is disabled\");\n      // ONE snapshot for the whole request (see the doc comment above).\n      const snapshot = resolveSnapshot?.();\n      // maxResults is owned by the DSH tool layer (it always passes its own);\n      // the plugin does not override it.\n      const maxResults = request.maxResults;\n      const baseChain = fallbackChain({\n        defaultProvider: cfg.defaultProvider,\n        fallbackOrder: cfg.fallbackOrder,\n      });\n      const chain = resolveSearchChain(\n        baseChain,\n        cfg.searchRoutingPolicy ?? \"ordered\",\n        routingState,\n      );\n\n      const attempts: Array<{ provider: string; outcome: string; latencyMs?: number }> = [];\n      let lastError: ProviderError | undefined;\n      const searchHints = extractSearchHints(request.query);\n\n      for (const providerName of chain) {\n        if (cfg.enabledProviders[providerName] === false) continue;\n        const entryInfo: CatalogEntry | undefined = snapshot?.get(providerName);\n        if (entryInfo?.config && entryInfo.config.enabled === false) {\n          attempts.push({ provider: providerName, outcome: \"skipped-disabled\" });\n          continue;\n        }\n        const adapter = adapterFor(providerName, snapshot);\n        if (!adapter) {\n          attempts.push({ provider: providerName, outcome: \"skipped-no-adapter\" });\n          continue;\n        }\n        let entries = await pools.poolOf(providerName);\n        const keyless = keylessOf(providerName, adapter, snapshot);\n        if (entries.length === 0 && keyless) {\n          // Keyless sources (self-hosted SearXNG, or a custom source with auth\n          // mode \"none\") execute with an empty key.\n          entries = [new PoolEntry(\"\", 0)];\n        } else if (entries.length === 0) {\n          attempts.push({ provider: providerName, outcome: \"skipped-no-keys\" });\n          continue;\n        }\n\n        // Auth-invalid keys stay unhealthy until the credential actually\n        // changes (refreshPool preserves healthy=false for persisted keys).\n        // If the whole pool is unusable, skip this provider — do NOT reset.\n        let usable = entries.filter((e) => e.healthy);\n        if (usable.length === 0) {\n          attempts.push({ provider: providerName, outcome: \"skipped-no-healthy-keys\" });\n          continue;\n        }\n\n        // Provider-level cooldown (Retry-After). The store uses its own clock\n        // (injectable for tests) — zero HTTP when cooling down.\n        if (healthStore?.isCoolingDown(providerName)) {\n          attempts.push({ provider: providerName, outcome: \"skipped-cooldown\" });\n          continue;\n        }\n\n        // Provider-internal key failover: on AUTH failures only, try the next\n        // healthy key in the SAME provider before falling back to another\n        // provider. Non-auth failures (429/5xx/network/timeout) do not rotate\n        // keys — they fall through to the next provider directly.\n        let providerLevelDecision: \"next-provider\" | \"break\" | \"terminal\" | null = null;\n        // Base URL from the request snapshot, so an override edit mid-request\n        // cannot make one attempt dial a different host than another.\n        const searchBaseUrl = entryInfo?.builtIn\n          ? entryInfo.endpoint?.effectiveBaseUrl\n          : cfg.providerBaseUrls[providerName];\n        while (usable.length > 0) {\n          const index = selectIndex(entries);\n          const entry = entries[index];\n          if (entry) reserveKey(entries, index);\n          const started = Date.now();\n          const providerOptions = cfg.providerOptions?.[providerName as keyof StoredProviderOptions];\n          try {\n            const outcome = await runWithTimeout(\n              (s) =>\n                adapter.search(request.query, maxResults, entry?.key ?? \"\", searchBaseUrl, {\n                  signal: s,\n                  options: providerOptions,\n                  hints: searchHints,\n                }),\n              cfg.providerAttemptTimeoutMs,\n              signal,\n            );\n            if (entry) markUsed(entries, index);\n            const latencyMs = Date.now() - started;\n            attempts.push({ provider: providerName, outcome: \"success\", latencyMs });\n            stats.record({ provider: providerName, outcome: \"success\", latencyMs });\n            return {\n              ...outcome,\n              truncated: false,\n              attempts,\n              backend: providerName,\n            };\n          } catch (error) {\n            const err = toProviderError(error);\n            const latencyMs = Date.now() - started;\n            const decision = classifyFailure(err);\n            // Caller cancellation terminates the whole chain — never fall back.\n            if (decision === \"terminal\") {\n              providerLevelDecision = \"terminal\";\n              lastError = err;\n              attempts.push({ provider: providerName, outcome: `failed:${err.code}`, latencyMs });\n              stats.record({ provider: providerName, outcome: `failed:${err.code}`, latencyMs });\n              break;\n            }\n            if (decision === \"non-retryable\") {\n              providerLevelDecision = \"break\";\n              lastError = err;\n              attempts.push({ provider: providerName, outcome: `failed:${err.code}`, latencyMs });\n              stats.record({ provider: providerName, outcome: `failed:${err.code}`, latencyMs });\n              break;\n            }\n            // retryable:\n            if (err.code === \"auth\") {\n              // key indicted → mark unhealthy, try the next key in this pool\n              markUnhealthy(entries, index);\n              attempts.push({ provider: providerName, outcome: `failed:${err.code}`, latencyMs });\n              stats.record({ provider: providerName, outcome: `failed:${err.code}`, latencyMs });\n              usable = entries.filter((e) => e.healthy);\n              continue;\n            }\n            // non-auth retryable (429/5xx/network/timeout) → next provider\n            lastError = err;\n            // Only rate-limit errors carry a server-requested cooldown.\n            if (err.code === \"rate-limit\" && typeof err.retryAfterMs === \"number\" && err.retryAfterMs > 0) {\n              healthStore?.cooldownFor(providerName, err.retryAfterMs, \"rate-limit\");\n            }\n            attempts.push({ provider: providerName, outcome: `failed:${err.code}`, latencyMs });\n            stats.record({ provider: providerName, outcome: `failed:${err.code}`, latencyMs });\n            providerLevelDecision = \"next-provider\";\n            break;\n          } finally {\n            if (entry) releaseKey(entries, index);\n          }\n        }\n\n        if (providerLevelDecision === \"terminal\") throw toWebError(lastError);\n        if (providerLevelDecision === \"break\") break;\n        // else fall through to the next provider in the chain\n      }\n\n      const reason = lastError\n        ? `${lastError.code}: ${lastError.message}`\n        : \"no usable provider\";\n      const err = new WebToolsWebError(`web search failed after ${attempts.length} attempt(s): ${reason}`);\n      err.attempts = attempts;\n      throw err;\n    },\n  };\n}\n\n/**\n * Build a `WebFetchProvider` for `ctx.web.registerFetchProvider`.\n * Routes fetch through configured native fetch providers (Tavily, Exa, Jina,\n * Firecrawl, Parallel) when available/healthy, and deterministically falls\n * back to the built-in generic HTTP fetcher (with SSRF guard + Defuddle Markdown\n * parsing) when native providers are unavailable, keyless, or fail.\n */\nexport function createFetchProvider(\n  resolveConfig: () => WebToolsRuntimeConfig,\n  resolveKeys: (providerName: string) => Promise<string>,\n  adapterRegistry: Record<string, ProviderAdapterLike> = PROVIDERS,\n  poolStore?: PoolStore,\n  healthStore?: ProviderHealthStore,\n  genericFetcher: typeof fetchGenericWebPage = fetchGenericWebPage,\n  resolveSnapshot?: () => ProviderSnapshot,\n): WebFetchProviderLike {\n  const pools = poolStore ?? createPoolStore(resolveKeys);\n\n  return {\n    id: `${PROVIDER_ID}-fetch`,\n    available() {\n      const cfg = resolveConfig();\n      // Built-in generic fetcher is always available as long as dsh-web-tools is enabled.\n      return cfg.enabled;\n    },\n    async fetch(request: { url: string }, signal?: AbortSignal) {\n      const cfg = resolveConfig();\n      const snapshot = resolveSnapshot?.();\n      const chain = fallbackChain({\n        defaultProvider: cfg.defaultProvider,\n        fallbackOrder: cfg.fallbackOrder,\n      });\n      const attempts: Array<{ provider: string; outcome: string }> = [];\n      let lastNativeError: ProviderError | undefined;\n      void lastNativeError; // retained for debugging inspection if native chain fails\n\n      // 1. Attempt native fetch from configured, enabled, fetch-capable providers\n      for (const providerName of chain) {\n        if (cfg.enabledProviders[providerName] === false) continue;\n        const nativeEntry = snapshot?.get(providerName);\n        if (nativeEntry?.config && nativeEntry.config.enabled === false) continue;\n        const adapter = (nativeEntry?.adapter as ProviderAdapterLike | undefined) ?? adapterRegistry[providerName];\n        // Custom sources are search-only (fetchCapable=false), so they are\n        // skipped here by construction and page fetching keeps using the\n        // built-in generic fetcher below.\n        if (!adapter || !adapter.fetchCapable) continue; // not a native fetch backend, skip\n        const entries = await pools.poolOf(providerName);\n        if (entries.length === 0) continue; // no credentials for this backend\n        const usable = entries.filter((e) => e.healthy);\n        if (usable.length === 0) continue; // all keys auth-unhealthy, skip provider\n        // Provider cooldown (Retry-After): skip without HTTP call.\n        if (healthStore?.isCoolingDown(providerName)) continue;\n        const index = selectIndex(entries);\n        const entry = entries[index];\n        if (entry) reserveKey(entries, index);\n        const providerOptions = cfg.providerOptions?.[providerName as keyof StoredProviderOptions];\n        // Native fetch endpoints stay on the official host: the base-URL\n        // override applies to SEARCH only (see endpoints.ts), because a gateway\n        // that proxies search may not proxy extraction.\n        const fetchBaseUrl = cfg.providerBaseUrls[providerName];\n        try {\n          const { text } = await runWithTimeout(\n            (sig) =>\n              adapter.fetch(request.url, entry?.key ?? \"\", fetchBaseUrl, {\n                signal: sig,\n                options: providerOptions,\n              }),\n            cfg.providerAttemptTimeoutMs,\n            signal,\n          );\n          if (entry) markUsed(entries, index);\n          attempts.push({ provider: providerName, outcome: \"success\" });\n          return {\n            url: request.url,\n            statusCode: 200,\n            body: { kind: \"text\" as const, content: text },\n            truncated: false,\n            backend: providerName,\n          };\n        } catch (error) {\n          const err = toProviderError(error);\n          if (err.code === \"auth\") markUnhealthy(entries, index);\n          if (err.code === \"rate-limit\" && typeof err.retryAfterMs === \"number\" && err.retryAfterMs > 0) {\n            healthStore?.cooldownFor(providerName, err.retryAfterMs, \"rate-limit\");\n          }\n          lastNativeError = err;\n          attempts.push({ provider: providerName, outcome: `failed:${err.code}` });\n          const decision = classifyFailure(err);\n          // Caller cancellation or terminal URL/SSRF errors should abort immediately without fallback\n          if (decision === \"terminal\") {\n            const terminalErr = toWebError(error);\n            terminalErr.attempts = attempts;\n            throw terminalErr;\n          }\n          if (decision === \"non-retryable\") break;\n          // retryable → try next fetch-capable provider in the chain\n        } finally {\n          if (entry) releaseKey(entries, index);\n        }\n      }\n\n      // If caller aborted, do not proceed to built-in generic fetch\n      if (signal?.aborted) {\n        const abortErr = new WebToolsWebError(\"web fetch aborted by caller\");\n        abortErr.code = \"WEB_ABORTED\";\n        abortErr.attempts = attempts;\n        throw abortErr;\n      }\n\n      // 2. Fallback to built-in generic HTTP fetcher (Defuddle + linkedom)\n      try {\n        const res = await genericFetcher(request.url, {\n          signal,\n          timeoutMs: cfg.providerAttemptTimeoutMs,\n        });\n        attempts.push({ provider: \"builtin-http\", outcome: \"success\" });\n        return {\n          url: res.finalUrl,\n          statusCode: res.statusCode,\n          body: { kind: \"text\" as const, content: res.content },\n          truncated: res.truncated,\n          backend: res.backend,\n          metadata: {\n            title: res.title,\n            author: res.author,\n            publishedAt: res.publishedAt,\n            description: res.description,\n          },\n        };\n      } catch (genErr: unknown) {\n        if (genErr instanceof GenericFetchError) {\n          attempts.push({ provider: \"builtin-http\", outcome: `failed:${genErr.code}` });\n          const webErr = new WebToolsWebError(\n            `web fetch failed: ${genErr.message}`,\n          );\n          webErr.code = genErr.code;\n          webErr.attempts = attempts;\n          throw webErr;\n        }\n\n        const fallbackErr = new WebToolsWebError(\n          `web fetch failed: ${genErr instanceof Error ? genErr.message : String(genErr)}`,\n        );\n        fallbackErr.attempts = attempts;\n        throw fallbackErr;\n      }\n    },\n  };\n}\n\n/** Convert any thrown value into a classified ProviderError. */\nfunction toProviderError(error: unknown): ProviderError {\n  if (typeof error === \"object\" && error !== null && \"code\" in error && typeof (error as ProviderError).code === \"string\") {\n    return error as ProviderError;\n  }\n  const message = error instanceof Error ? error.message : String(error);\n  const err = new Error(message) as ProviderError;\n  err.code = \"network\";\n  return err;\n}\n\n/** Wrap an unknown failure from a provider call into a WebToolsWebError. */\nfunction toWebError(error: unknown): WebToolsWebError {\n  const p = toProviderError(error);\n  const err = new WebToolsWebError(p.message);\n  // preserve cancellation semantics: aborted stays aborted\n  if (p.code === \"aborted\") err.code = \"WEB_ABORTED\";\n  return err;\n}\n\n/**\n * Run a provider attempt with a real abort: the provider's fetch receives a\n * signal that fires on EITHER the caller's cancellation OR this attempt's\n * timeout, so a timeout genuinely aborts the in-flight HTTP request (no\n * background request lingering / burning quota).\n *\n * Distinguishes the two cases:\n *  - caller abort  → rejects with `aborted` (terminal; the chain stops)\n *  - attempt timeout → rejects with `timeout` (retryable; fallback proceeds)\n *\n * @param run - the provider call; receives the merged abort signal.\n * @param timeoutMs - per-attempt budget; <=0 disables the timer.\n * @param externalSignal - the caller's AbortSignal (optional).\n */\nasync function runWithTimeout<T>(\n  run: (signal: AbortSignal) => Promise<T>,\n  timeoutMs: number,\n  externalSignal?: AbortSignal,\n): Promise<T> {\n  const controller = new AbortController();\n  // Explicit abort-cause state. A caller abort CLEARS the timer immediately,\n  // so a late timer callback can never flip a caller cancellation into a\n  // timeout (which would wrongly trigger fallback).\n  let abortCause: \"caller\" | \"timeout\" | undefined;\n  let timer: ReturnType<typeof setTimeout> | undefined;\n\n  const clearTimer = () => {\n    if (timer) {\n      clearTimeout(timer);\n      timer = undefined;\n    }\n  };\n\n  const onExternalAbort = () => {\n    abortCause = \"caller\";\n    clearTimer();\n    controller.abort(externalSignal?.reason);\n  };\n\n  if (externalSignal) {\n    if (externalSignal.aborted) throw providerErrorOf(\"aborted\", \"search aborted by caller\");\n    externalSignal.addEventListener(\"abort\", onExternalAbort, { once: true });\n  }\n\n  if (Number.isFinite(timeoutMs) && timeoutMs > 0) {\n    timer = setTimeout(() => {\n      if (abortCause !== undefined) return; // already aborted by caller\n      abortCause = \"timeout\";\n      controller.abort(new Error(`provider timed out after ${timeoutMs}ms`));\n    }, timeoutMs);\n  }\n\n  try {\n    const value = await run(controller.signal);\n    if (controller.signal.aborted) {\n      throw providerErrorOf(abortCause === \"timeout\" ? \"timeout\" : \"aborted\", controller.signal.reason?.message ?? \"attempt aborted\");\n    }\n    return value;\n  } catch (error) {\n    // If OUR timer fired, the provider's own abort (whatever code it raised)\n    // is a TIMEOUT — even if the adapter rethrew its own 'aborted'. External\n    // cancellation is only 'aborted' when abortCause is not \"timeout\".\n    if (controller.signal.aborted) {\n      throw providerErrorOf(abortCause === \"timeout\" ? \"timeout\" : \"aborted\", controller.signal.reason instanceof Error ? controller.signal.reason.message : String(controller.signal.reason ?? \"aborted\"));\n    }\n    throw error;\n  } finally {\n    clearTimer();\n    if (externalSignal) externalSignal.removeEventListener(\"abort\", onExternalAbort);\n  }\n}\n\n/** Build a classified ProviderError with a code + message. */\nfunction providerErrorOf(code: ProviderErrorCode, message: string): ProviderError {\n  const err = new Error(message) as ProviderError;\n  err.code = code;\n  return err;\n}\n"
