      "path": "src/host/sources/registry.ts",
      "content": "import { validatePlatformUrl } from \"../browser/paths.ts\";\nimport { fallbackSearchToGeneralWeb, fallbackFetchToGeneralWeb } from \"./web-fallback.ts\";\nimport type {\n  SpecializedSource,\n  SpecializedPlatformId,\n  SourceStatus,\n  SourceSearchRequest,\n  SourceSearchOutcome,\n  SourceFetchOutcome,\n} from \"./types.ts\";\nimport type { WebSearchProviderLike, WebFetchProviderLike } from \"../registry.ts\";\n\nexport class SpecializedSourceRegistry {\n  private sources = new Map<SpecializedPlatformId, SpecializedSource>();\n  private fallbackSearchProvider?: WebSearchProviderLike;\n  private fallbackFetchProvider?: WebFetchProviderLike;\n  private platformEnabled: Record<string, boolean> = { xiaohongshu: true, x: true };\n\n  registerSource(source: SpecializedSource): void {\n    this.sources.set(source.id, source);\n  }\n\n  setPlatformEnabled(enabledMap: Record<string, boolean>): void {\n    this.platformEnabled = { ...this.platformEnabled, ...enabledMap };\n  }\n\n  isPlatformEnabled(platform: SpecializedPlatformId): boolean {\n    return this.platformEnabled[platform] !== false;\n  }\n\n  unregisterSource(id: SpecializedPlatformId): void {\n    this.sources.delete(id);\n  }\n\n  getSource(id: SpecializedPlatformId): SpecializedSource | undefined {\n    return this.sources.get(id);\n  }\n\n  setFallbackProviders(\n    search?: WebSearchProviderLike,\n    fetch?: WebFetchProviderLike,\n  ): void {\n    this.fallbackSearchProvider = search;\n    this.fallbackFetchProvider = fetch;\n  }\n\n  private inFlightStatus?: Promise<SourceStatus[]>;\n\n  async getPlatformStatuses(): Promise<SourceStatus[]> {\n    if (this.inFlightStatus) {\n      return this.inFlightStatus;\n    }\n    this.inFlightStatus = (async () => {\n      try {\n        const platformIds: SpecializedPlatformId[] = [\"xiaohongshu\", \"x\"];\n        const statusPromises = platformIds.map(async (id): Promise<SourceStatus> => {\n          const source = this.sources.get(id);\n          if (!source) {\n            return {\n              id,\n              name: id === \"xiaohongshu\" ? \"小红书\" : \"Twitter / X\",\n              enabled: this.isPlatformEnabled(id),\n              runtimeAvailable: false,\n              runtimeState: \"unavailable\",\n              authenticated: false,\n            };\n          }\n          try {\n            const s = await source.status();\n            return {\n              ...s,\n              enabled: this.isPlatformEnabled(id),\n            };\n          } catch (err: any) {\n            return {\n              id,\n              name: source.name,\n              enabled: this.isPlatformEnabled(id),\n              runtimeAvailable: false,\n              runtimeState: \"error\",\n              authenticated: false,\n              lastError: err?.message || String(err),\n              lastCheckedAt: Date.now(),\n            };\n          }\n        });\n        return await Promise.all(statusPromises);\n      } finally {\n        this.inFlightStatus = undefined;\n      }\n    })();\n    return this.inFlightStatus;\n  }\n\n  async routeSearch(\n    query: string,\n    req?: SourceSearchRequest,\n    signal?: AbortSignal,\n  ): Promise<SourceSearchOutcome> {\n    return this.search(query, req, signal);\n  }\n\n  async search(\n    query: string,\n    req?: SourceSearchRequest,\n    signal?: AbortSignal,\n  ): Promise<SourceSearchOutcome> {\n    const platform = req?.hints?.platform;\n    if (!platform) {\n      if (this.fallbackSearchProvider) {\n        const res = await this.fallbackSearchProvider.search({ query, maxResults: req?.maxResults }, signal);\n        const items = (res.sources || []).map((s) => ({\n          id: s.url,\n          title: s.title || s.url,\n          url: s.url,\n          snippet: s.snippet,\n          platform: \"general\" as const,\n        }));\n        return { items, retrievalMode: \"general-web\" };\n      }\n      return { items: [] };\n    }\n\n    const source = this.sources.get(platform);\n    if (!source || !this.isPlatformEnabled(platform)) {\n      return fallbackSearchToGeneralWeb(\n        query,\n        platform,\n        this.fallbackSearchProvider,\n        req?.maxResults,\n        signal,\n      );\n    }\n\n    const nativeQuery = req?.hints?.cleanQuery?.trim() || query;\n    const outcome = await source.search(nativeQuery, req, signal);\n    // If native search succeeded (even 0 results), keep native outcome!\n    if (outcome.error === undefined) {\n      return { ...outcome, retrievalMode: \"native-browser\" };\n    }\n\n    // Do not hide platform authentication/access failures behind indexed web\n    // results. They cannot provide native details or real comments and would\n    // make an explicit platform search look successful when it was not.\n    if (signal?.aborted || outcome.error.code === \"aborted\") {\n      return outcome;\n    }\n    if (!outcome.error.retryable) {\n      return outcome;\n    }\n\n    // Retryable browser/runtime failures may still use indexed discovery.\n    return fallbackSearchToGeneralWeb(\n      query,\n      platform,\n      this.fallbackSearchProvider,\n      req?.maxResults,\n      signal,\n    );\n  }\n\n  async routeFetch(url: string, signal?: AbortSignal): Promise<SourceFetchOutcome> {\n    return this.fetch(url, signal);\n  }\n\n  async fetch(url: string, signal?: AbortSignal): Promise<SourceFetchOutcome> {\n    let targetPlatform: SpecializedPlatformId | undefined;\n    if (validatePlatformUrl(url, \"xiaohongshu\")) {\n      targetPlatform = \"xiaohongshu\";\n    } else if (validatePlatformUrl(url, \"x\")) {\n      targetPlatform = \"x\";\n    }\n\n    if (!targetPlatform) {\n      if (this.fallbackFetchProvider) {\n        const res = await this.fallbackFetchProvider.fetch({ url }, signal);\n        return {\n          item: {\n            id: res.url || url,\n            title: res.metadata?.title || \"Web Page\",\n            url: res.url || url,\n            text: res.body?.content || \"\",\n            platform: \"general\",\n            author: res.metadata?.author ? { name: res.metadata.author } : undefined,\n            publishedAt: res.metadata?.publishedAt,\n          },\n          retrievalMode: \"general-web\",\n        };\n      }\n      return { error: { code: \"runtime-unavailable\", message: \"No fetch provider available\", retryable: false } };\n    }\n\n    const source = this.sources.get(targetPlatform);\n    if (!source || !this.isPlatformEnabled(targetPlatform)) {\n      return fallbackFetchToGeneralWeb(url, this.fallbackFetchProvider, signal);\n    }\n\n    const outcome = await source.fetch(url, signal);\n    if (outcome.error === undefined && outcome.item) {\n      return { ...outcome, retrievalMode: \"native-browser\" };\n    }\n\n    if (signal?.aborted || outcome.error?.code === \"aborted\") {\n      return outcome;\n    }\n\n    // A source marks platform-auth, access-control, and invalid-detail errors\n    // as non-retryable. Do not hide that concrete result behind a potentially\n    // long general-provider chain that cannot recover native comments/session\n    // data and may consume the tool's entire timeout budget.\n    if (outcome.error && !outcome.error.retryable) {\n      return outcome;\n    }\n\n    return fallbackFetchToGeneralWeb(url, this.fallbackFetchProvider, signal);\n  }\n}\n"
    },
    {
      "path": "src/host/browser/session-manager.ts",
      "content": "import { CdpClient } from \"./cdp/client.ts\";\nimport { fetchWebSocketDebuggerUrl } from \"./cdp/connection.ts\";\nimport { CdpPage } from \"./cdp/page.ts\";\nimport { UrlDisallowedError } from \"./cdp/errors.ts\";\nimport { locateBrowser } from \"./locator.ts\";\nimport { validatePlatformUrl } from \"./paths.ts\";\nimport { ProfileStore } from \"./profile-store.ts\";\nimport { StateStore } from \"./state-store.ts\";\nimport { verifyLiveBrowserSession, type LiveSessionVerifier } from \"./live-auth-verifier.ts\";\nimport { detectXhsPageState } from \"./xiaohongshu-page-state.ts\";\nimport { isPidAlive as defaultIsPidAlive, launchBrowserProcess, type SpawnedBrowserProcess } from \"./process-manager.ts\";\nimport type {\n  BrowserInfo,\n  BrowserPlatform,\n  BrowserRunMode,\n  BrowserSessionStatus,\n  CdpPageLease,\n  NativeBrowserRuntime,\n  RunningBrowserState,\n} from \"./types.ts\";\n\nexport type ProcessLauncher = (\n  browser: BrowserInfo,\n  profileDir: string,\n  initialUrl?: string,\n  minimized?: boolean,\n  headless?: boolean,\n) => Promise<SpawnedBrowserProcess>;\n\nexport type CdpClientFactory = (port: number, signal?: AbortSignal) => Promise<CdpClient>;\nexport type PidChecker = (pid: number) => boolean;\nexport type PidKiller = (pid: number) => void;\n\ninterface RunningSession {\n  platform: BrowserPlatform;\n  browser: BrowserInfo;\n  port: number;\n  pid?: number;\n  cdp: CdpClient;\n  profileDir: string;\n  mode: BrowserRunMode;\n  startedAt: number;\n  process?: import(\"node:child_process\").ChildProcess;\n}\n\ntype PlatformLifecycleState =\n  | \"stopped\"\n  | \"starting\"\n  | \"ready\"\n  | \"transitioning\"\n  | \"stopping\"\n  | \"error\";\n\ninterface PlatformLifecycleRecord {\n  platform: BrowserPlatform;\n  state: PlatformLifecycleState;\n  session?: RunningSession;\n  targetMode?: BrowserRunMode;\n  activeLeases: number;\n  idleTimer?: NodeJS.Timeout;\n  queue: Promise<unknown>;\n  pendingCancel?: boolean;\n}\n\nconst PLATFORM_AUTH_CONFIG: Record<\n  BrowserPlatform,\n  {\n    initialUrl: string;\n    domains: string[];\n    requiredCookies: string[];\n    verifyPredicate: (cookieNames: Set<string>) => boolean;\n  }\n> = {\n  xiaohongshu: {\n    initialUrl: \"https://www.xiaohongshu.com/explore\",\n    domains: [\"xiaohongshu.com\"],\n    requiredCookies: [\"a1\", \"web_session\"],\n    verifyPredicate: (names) => names.has(\"a1\") && names.has(\"web_session\"),\n  },\n  x: {\n    initialUrl: \"https://x.com/home\",\n    domains: [\"x.com\", \"twitter.com\"],\n    requiredCookies: [\"auth_token\", \"ct0\"],\n    verifyPredicate: (names) => names.has(\"auth_token\") && names.has(\"ct0\"),\n  },\n};\n\nexport class SessionManager implements NativeBrowserRuntime {\n  private records = new Map<BrowserPlatform, PlatformLifecycleRecord>();\n  private profileStore: ProfileStore;\n  private stateStore: StateStore;\n  private readonly browserChoice: \"auto\" | \"edge\" | \"chrome\" | string;\n  private readonly idleShutdownMs: number;\n  private readonly launcher: ProcessLauncher;\n  private readonly cdpFactory: CdpClientFactory;\n  private readonly isPidAliveFn: PidChecker;\n  private readonly killPidFn: PidKiller;\n  private readonly liveSessionVerifier: LiveSessionVerifier;\n  private disposed = false;\n\n  constructor(\n    browserChoice: \"auto\" | \"edge\" | \"chrome\" | string = \"auto\",\n    baseDirOverride?: string,\n    idleShutdownMs = 300000,\n    launcher: ProcessLauncher = launchBrowserProcess,\n    cdpFactory: CdpClientFactory = async (port, signal) => {\n      const wsUrl = await fetchWebSocketDebuggerUrl(port, 12000, signal);\n      const cdp = new CdpClient(wsUrl);\n      await cdp.connect(5000);\n      return cdp;\n    },\n    isPidAliveFn: PidChecker = defaultIsPidAlive,\n    killPidFn: PidKiller = (pid) => {\n      try {\n        process.kill(pid);\n      } catch {}\n    },\n    liveSessionVerifier: LiveSessionVerifier = verifyLiveBrowserSession,\n  ) {\n    this.browserChoice = browserChoice;\n    this.idleShutdownMs = idleShutdownMs;\n    this.launcher = launcher;\n    this.cdpFactory = cdpFactory;\n    this.isPidAliveFn = isPidAliveFn;\n    this.killPidFn = killPidFn;\n    this.liveSessionVerifier = liveSessionVerifier;\n    this.profileStore = new ProfileStore(baseDirOverride);\n    this.stateStore = new StateStore(baseDirOverride);\n  }\n\n  private getRecord(platform: BrowserPlatform): PlatformLifecycleRecord {\n    let rec = this.records.get(platform);\n    if (!rec) {\n      rec = {\n        platform,\n        state: \"stopped\",\n        activeLeases: 0,\n        queue: Promise.resolve(),\n      };\n      this.records.set(platform, rec);\n    }\n    return rec;\n  }\n\n  private enqueue<T>(platform: BrowserPlatform, task: () => Promise<T>): Promise<T> {\n    const rec = this.getRecord(platform);\n    const resultPromise = rec.queue.then(task, task);\n    rec.queue = resultPromise.then(() => {}, () => {});\n    return resultPromise;\n  }\n\n  async detect(): Promise<BrowserInfo | null> {\n    try {\n      return locateBrowser(this.browserChoice);\n    } catch {\n      return null;\n    }\n  }\n\n  async checkAuthentication(platform: BrowserPlatform): Promise<boolean> {\n    const session = await this.acquireSession(platform, \"headless\", undefined, undefined);\n    return this.internalCheckAuth(session);\n  }\n\n  async verifyAuthenticationForOperation(\n    platform: BrowserPlatform,\n    signal?: AbortSignal,\n    mode: BrowserRunMode = \"headless\",\n  ): Promise<boolean> {\n    try {\n      // Metadata is only a cached observation. A transient page/target race can\n      // make an earlier probe write `sessionEstablished: false` even though the\n      // dedicated profile still contains valid cookies. Operations must verify\n      // the real profile so the next search can self-heal without another login.\n      const session = await this.acquireSession(platform, mode, undefined, signal);\n      const isAuth = await this.internalCheckAuth(session, signal);\n      if (isAuth) {\n        this.profileStore.saveMetadata(platform, {\n          platform,\n          sessionEstablished: true,\n          browserKind: session.browser.kind,\n          lastVerifiedAt: Date.now(),\n        });\n        return true;\n      } else {\n        this.profileStore.saveMetadata(platform, {\n          platform,\n          sessionEstablished: false,\n          browserKind: session.browser.kind,\n          lastVerifiedAt: Date.now(),\n        });\n        return false;\n      }\n    } catch {\n      return false;\n    }\n  }\n\n  private async internalCheckAuth(session: RunningSession, signal?: AbortSignal): Promise<boolean> {\n    try {\n      if (!await this.hasRequiredCookies(session)) return false;\n      return await this.liveSessionVerifier({\n        platform: session.platform,\n        cdp: session.cdp,\n        signal,\n      });\n    } catch {\n      return false;\n    }\n  }\n\n  private async hasRequiredCookies(session: RunningSession): Promise<boolean> {\n    const config = PLATFORM_AUTH_CONFIG[session.platform];\n    try {\n      const res = await session.cdp.send<{\n        cookies: Array<{ name: string; domain: string }>;\n      }>(\"Storage.getCookies\");\n      const names = new Set(\n        (res.cookies || [])\n          .filter((cookie) => {\n            const cookieDomain = (cookie.domain || \"\").toLowerCase().replace(/^\\./, \"\");\n            return config.domains.some((domain) => {\n              const target = domain.toLowerCase().replace(/^\\./, \"\");\n              return cookieDomain === target || cookieDomain.endsWith(\".\" + target);\n            });\n          })\n          .map((cookie) => cookie.name),\n      );\n      return config.verifyPredicate(names);\n    } catch {\n      return false;\n    }\n  }\n\n  async status(platform: BrowserPlatform): Promise<BrowserSessionStatus> {\n    const browser = await this.detect();\n    if (!browser) {\n      return {\n        platform,\n        runtimeAvailable: false,\n        runtimeState: \"unavailable\",\n        authState: \"unknown\",\n        authenticated: false,\n      };\n    }\n\n    const rec = this.getRecord(platform);\n    if (rec.session) {\n      const auth = await this.internalCheckAuth(rec.session);\n      this.profileStore.saveMetadata(platform, {\n        platform,\n        sessionEstablished: auth,\n        browserKind: rec.session.browser.kind,\n        lastVerifiedAt: Date.now(),\n      });\n      return {\n        platform,\n        runtimeAvailable: true,\n        runtimeState: \"ready\",\n        browser: rec.session.browser,\n        mode: rec.session.mode,\n        authState: auth ? \"authenticated\" : \"signed-out\",\n        authenticated: auth,\n        sessionEstablished: auth,\n        verifiedAt: Date.now(),\n      };\n    }\n\n    // Check stored runtime.json for already running process\n    const stored = this.stateStore.loadState(platform);\n    if (stored && this.isPidAliveFn(stored.pid)) {\n      try {\n        const cdp = await this.cdpFactory(stored.port);\n        const tempSession: RunningSession = {\n          platform,\n          browser: { kind: stored.browserKind, executablePath: browser.executablePath },\n          port: stored.port,\n          pid: stored.pid,\n          cdp,\n          profileDir: stored.profileDir,\n          mode: stored.mode,\n          startedAt: stored.startedAt,\n        };\n        cdp.onClose(() => {\n          if (rec.session?.cdp === cdp) {\n            rec.session = undefined;\n            rec.state = \"stopped\";\n            this.stateStore.clearState(platform);\n          }\n        });\n        const authenticated = await this.internalCheckAuth(tempSession);\n        this.profileStore.saveMetadata(platform, {\n          platform,\n          sessionEstablished: authenticated,\n          browserKind: tempSession.browser.kind,\n          lastVerifiedAt: Date.now(),\n        });\n        rec.session = tempSession;\n        rec.state = \"ready\";\n        this.scheduleIdleTimer(rec);\n        return {\n          platform,\n          runtimeAvailable: true,\n          runtimeState: \"ready\",\n          browser,\n          mode: tempSession.mode,\n          authState: authenticated ? \"authenticated\" : \"signed-out\",\n          authenticated,\n          sessionEstablished: authenticated,\n          verifiedAt: Date.now(),\n        };\n      } catch {\n        this.stateStore.clearState(platform);\n      }\n    }\n\n    // Check profile metadata: did user establish session previously?\n    const meta = this.profileStore.loadMetadata(platform);\n    if (meta && meta.sessionEstablished) {\n      // Persisted metadata only proves that this profile established a session\n      // before. Without a running browser, live usability is unknown even when\n      // the previous verification was recent; the status route will probe it.\n      return {\n        platform,\n        runtimeAvailable: true,\n        runtimeState: \"stopped\",\n        browser,\n        authState: \"unknown\",\n        authenticated: false,\n        sessionEstablished: true,\n        verifiedAt: meta.lastVerifiedAt,\n      };\n    }\n\n    return {\n      platform,\n      runtimeAvailable: true,\n      runtimeState: \"stopped\",\n      browser,\n      authState: \"signed-out\",\n      authenticated: false,\n    };\n  }\n\n  async login(\n    platform: BrowserPlatform,\n    signal?: AbortSignal,\n  ): Promise<BrowserSessionStatus> {\n    if (this.disposed) throw new Error(\"NativeBrowserRuntime is disposed\");\n    if (signal?.aborted) throw new Error(\"Login aborted\");\n\n    const config = PLATFORM_AUTH_CONFIG[platform];\n\n    // Login is an exclusive interactive operation.\n    // It acquires an operation lease to prevent idle shutdown during polling.\n    const rec = this.getRecord(platform);\n    this.retainLease(rec);\n    let loginPage: CdpPage | undefined;\n\n    try {\n      const session = await this.acquireSession(platform, \"interactive\", config.initialUrl, signal);\n\n      // A new login attempt disarms stale metadata immediately. It becomes\n      // established again only after cookies and live page usability agree.\n      this.profileStore.saveMetadata(platform, {\n        platform,\n        sessionEstablished: false,\n        browserKind: session.browser.kind,\n        lastVerifiedAt: Date.now(),\n      });\n\n      loginPage = await this.prepareInteractiveLogin(session, config.initialUrl, signal);\n      if (platform === \"xiaohongshu\" && !loginPage) {\n        throw new Error(\"Unable to inspect the Xiaohongshu login page\");\n      }\n\n      const start = Date.now();\n      const timeoutMs = 300000; // 5 min timeout for manual interaction\n      let authenticated = false;\n      let consecutiveReadyStates = 0;\n\n      while (Date.now() - start < timeoutMs) {\n        if (signal?.aborted || this.disposed) throw new Error(\"Login aborted by user\");\n        const hasCookies = await this.hasRequiredCookies(session);\n        if (platform === \"xiaohongshu\") {\n          try {\n            const pageState = hasCookies && loginPage\n              ? await loginPage.call(detectXhsPageState, [], signal)\n              : undefined;\n            consecutiveReadyStates = pageState === \"ready\" ? consecutiveReadyStates + 1 : 0;\n            authenticated = consecutiveReadyStates >= 2;\n          } catch {\n            consecutiveReadyStates = 0;\n            authenticated = false;\n          }\n        } else {\n          authenticated = hasCookies;\n        }\n        if (authenticated) {\n          this.profileStore.saveMetadata(platform, {\n            platform,\n            sessionEstablished: true,\n            browserKind: session.browser.kind,\n            lastVerifiedAt: Date.now(),\n          });\n          // Minimize window after login success\n          try {\n            const targets = await session.cdp.send<{\n              targetInfos: Array<{ targetId: string; type: string }>;\n            }>(\"Target.getTargets\");\n            const pageTarget = targets.targetInfos?.find((t) => t.type === \"page\");\n            if (pageTarget) {\n              const boundsRes = await session.cdp.send<{ windowId: number }>(\n                \"Browser.getWindowForTarget\",\n                { targetId: pageTarget.targetId },\n              );\n              if (boundsRes?.windowId) {\n                await session.cdp.send(\"Browser.setWindowBounds\", {\n                  windowId: boundsRes.windowId,\n                  bounds: { windowState: \"minimized\" },\n                });\n              }\n            }\n          } catch {\n            // Ignore minimize failure\n          }\n          break;\n        }\n        await new Promise((r) => setTimeout(r, 1500));\n      }\n\n      return {\n        platform,\n        runtimeAvailable: true,\n        runtimeState: \"ready\",\n        browser: session.browser,\n        mode: session.mode,\n        authState: authenticated ? \"authenticated\" : \"signed-out\",\n        authenticated,\n        verifiedAt: Date.now(),\n        lastError: authenticated ? undefined : \"Login timed out\",\n      };\n    } finally {\n      if (loginPage) {\n        try {\n          await rec.session?.cdp.send(\n            \"Target.detachFromTarget\",\n            { sessionId: loginPage.sessionId },\n          );\n        } catch {\n          // Detaching the inspector must never close the user's login tab.\n        }\n      }\n      this.releaseLease(rec);\n    }\n  }\n\n  private async prepareInteractiveLogin(\n    session: RunningSession,\n    initialUrl: string,\n    signal?: AbortSignal,\n  ): Promise<CdpPage | undefined> {\n    try {\n      const targets = await session.cdp.send<{\n        targetInfos: Array<{ targetId: string; type: string }>;\n      }>(\"Target.getTargets\");\n      let pageTarget = targets.targetInfos?.find((t) => t.type === \"page\");\n\n      if (!pageTarget) {\n        const createRes = await session.cdp.send<{ targetId: string }>(\n          \"Target.createTarget\",\n          { url: \"about:blank\" },\n          undefined,\n          signal,\n        );\n        pageTarget = { targetId: createRes.targetId, type: \"page\" };\n      }\n\n      const attachRes = await session.cdp.send<{ sessionId: string }>(\n        \"Target.attachToTarget\",\n        { targetId: pageTarget.targetId, flatten: true },\n        undefined,\n        signal,\n      );\n      const page = new CdpPage(pageTarget.targetId, attachRes.sessionId, session.cdp, async () => {});\n      await page.navigate(initialUrl, signal);\n\n      const boundsRes = await session.cdp.send<{ windowId: number }>(\n        \"Browser.getWindowForTarget\",\n        { targetId: pageTarget.targetId },\n      );\n      if (boundsRes?.windowId) {\n        await session.cdp.send(\"Browser.setWindowBounds\", {\n          windowId: boundsRes.windowId,\n          bounds: { windowState: \"normal\" },\n        });\n      }\n      return page;\n    } catch {\n      // Non-critical interactive prep error\n      return undefined;\n    }\n  }\n\n  async openPage(\n    platform: BrowserPlatform,\n    url: string,\n    signal?: AbortSignal,\n    mode: BrowserRunMode = \"headless\",\n  ): Promise<CdpPageLease> {\n    if (!validatePlatformUrl(url, platform)) {\n      throw new UrlDisallowedError(url, platform);\n    }\n\n    const page = await this.createPage(platform, signal, mode);\n    try {\n      await page.navigate(url, signal);\n      return page;\n    } catch (err) {\n      await page.close();\n      throw err;\n    }\n  }\n\n  async createPage(\n    platform: BrowserPlatform,\n    signal?: AbortSignal,\n    mode: BrowserRunMode = \"headless\",\n  ): Promise<CdpPageLease> {\n    if (this.disposed) throw new Error(\"NativeBrowserRuntime is disposed\");\n    if (signal?.aborted) throw new Error(\"createPage aborted\");\n\n    const rec = this.getRecord(platform);\n    this.retainLease(rec);\n\n    try {\n      const session = await this.acquireSession(platform, mode, undefined, signal);\n\n      const createRes = await session.cdp.send<{ targetId: string }>(\n        \"Target.createTarget\",\n        { url: \"about:blank\" },\n        undefined,\n        signal,\n      );\n      const targetId = createRes.targetId;\n\n      const attachRes = await session.cdp.send<{ sessionId: string }>(\n        \"Target.attachToTarget\",\n        { targetId, flatten: true },\n        undefined,\n        signal,\n      );\n      const sessionId = attachRes.sessionId;\n\n      let closed = false;\n      return new CdpPage(\n        targetId,\n        sessionId,\n        session.cdp,\n        async () => {\n          if (closed) return;\n          closed = true;\n          try {\n            await session.cdp.send(\"Target.closeTarget\", { targetId });\n          } catch {\n            // Ignore closeTarget failure\n          } finally {\n            this.releaseLease(rec);\n          }\n        },\n        (url) => {\n          if (!validatePlatformUrl(url, platform)) {\n            throw new UrlDisallowedError(url, platform);\n          }\n        },\n      );\n    } catch (err) {\n      this.releaseLease(rec);\n      throw err;\n    }\n  }\n\n  private retainLease(rec: PlatformLifecycleRecord) {\n    rec.activeLeases++;\n    if (rec.idleTimer) {\n      clearTimeout(rec.idleTimer);\n      rec.idleTimer = undefined;\n    }\n  }\n\n  private releaseLease(rec: PlatformLifecycleRecord) {\n    if (rec.activeLeases > 0) {\n      rec.activeLeases--;\n    }\n    if (rec.activeLeases === 0) {\n      this.scheduleIdleTimer(rec);\n    }\n  }\n\n  private scheduleIdleTimer(rec: PlatformLifecycleRecord) {\n    if (rec.idleTimer) {\n      clearTimeout(rec.idleTimer);\n      rec.idleTimer = undefined;\n    }\n    if (this.idleShutdownMs > 0 && rec.activeLeases === 0 && rec.session && !this.disposed) {\n      rec.idleTimer = setTimeout(() => {\n        if (rec.activeLeases === 0) {\n          this.stop(rec.platform).catch(() => {});\n        }\n      }, this.idleShutdownMs);\n    }\n  }\n\n  private async acquireSession(\n    platform: BrowserPlatform,\n    desiredMode: BrowserRunMode,\n    initialUrl?: string,\n    signal?: AbortSignal,\n  ): Promise<RunningSession> {\n    return this.enqueue(platform, async () => {\n      if (this.disposed) throw new Error(\"NativeBrowserRuntime is disposed\");\n      if (signal?.aborted) throw new Error(\"Operation aborted\");\n\n      const rec = this.getRecord(platform);\n\n      // Check if current session matches desired mode\n      if (rec.session && rec.state === \"ready\") {\n        if (rec.session.mode === desiredMode) {\n          return rec.session;\n        }\n        // Mode transition: stop existing browser before launching with desired mode\n        rec.state = \"transitioning\";\n        await this.internalStop(rec);\n      }\n\n      rec.state = \"starting\";\n      rec.targetMode = desiredMode;\n      rec.pendingCancel = false;\n\n      const browser = await this.detect();\n      if (!browser) {\n        rec.state = \"error\";\n        throw new Error(\"No supported browser (Edge / Chrome) found\");\n      }\n\n      const profileDir = this.profileStore.ensureProfileDir(platform);\n      const isVisible = desiredMode === \"interactive\";\n      const config = PLATFORM_AUTH_CONFIG[platform];\n      const startUrl = initialUrl || (isVisible ? config.initialUrl : undefined);\n\n      let spawned: SpawnedBrowserProcess;\n      try {\n        spawned = await this.launcher(browser, profileDir, startUrl, isVisible, !isVisible);\n      } catch (err) {\n        rec.state = \"error\";\n        throw err;\n      }\n\n      if (rec.pendingCancel || this.disposed || signal?.aborted) {\n        if (spawned.process.pid) {\n          this.killPidFn(spawned.process.pid);\n        }\n        rec.state = \"stopped\";\n        throw new Error(\"Session acquisition cancelled\");\n      }\n\n      let cdp: CdpClient;\n      try {\n        cdp = await this.cdpFactory(spawned.port, signal);\n      } catch (err) {\n        if (spawned.process.pid) {\n          this.killPidFn(spawned.process.pid);\n        }\n        rec.state = \"error\";\n        throw err;\n      }\n\n      if (rec.pendingCancel || this.disposed || signal?.aborted) {\n        cdp.close();\n        if (spawned.process.pid) {\n          this.killPidFn(spawned.process.pid);\n        }\n        rec.state = \"stopped\";\n        throw new Error(\"Session acquisition cancelled\");\n      }\n\n      const session: RunningSession = {\n        platform,\n        browser,\n        port: spawned.port,\n        pid: spawned.process.pid,\n        cdp,\n        profileDir,\n        mode: desiredMode,\n        startedAt: spawned.startedAt,\n        process: spawned.process,\n      };\n\n      cdp.onClose(() => {\n        if (rec.session?.cdp === cdp) {\n          rec.session = undefined;\n          rec.state = \"stopped\";\n          this.stateStore.clearState(platform);\n        }\n      });\n\n      const state: RunningBrowserState = {\n        pid: spawned.process.pid || 0,\n        port: spawned.port,\n        browserKind: browser.kind,\n        profileDir,\n        mode: desiredMode,\n        startedAt: spawned.startedAt,\n      };\n      this.stateStore.saveState(platform, state);\n\n      spawned.process.on(\"exit\", () => {\n        if (rec.session?.process === spawned.process) {\n          rec.session = undefined;\n          rec.state = \"stopped\";\n          this.stateStore.clearState(platform);\n        }\n      });\n\n      rec.session = session;\n      rec.state = \"ready\";\n      if (rec.activeLeases === 0) {\n        this.scheduleIdleTimer(rec);\n      }\n      return session;\n    });\n  }\n\n  private async internalStop(rec: PlatformLifecycleRecord): Promise<void> {\n    rec.pendingCancel = true;\n    if (rec.idleTimer) {\n      clearTimeout(rec.idleTimer);\n      rec.idleTimer = undefined;\n    }\n\n    const session = rec.session;\n    rec.session = undefined;\n    rec.state = \"stopped\";\n\n    if (session) {\n      try {\n        await session.cdp.send(\"Browser.close\", {}, undefined, undefined, 1000);\n      } catch {\n        // Fallback to socket close & kill\n      }\n      session.cdp.close();\n\n      const pid = session.pid;\n      if (pid) {\n        let dead = !this.isPidAliveFn(pid);\n        const start = Date.now();\n        while (!dead && Date.now() - start < 500) {\n          await new Promise((r) => setTimeout(r, 50));\n          dead = !this.isPidAliveFn(pid);\n        }\n\n        if (!dead) {\n          this.killPidFn(pid);\n          const killStart = Date.now();\n          while (!dead && Date.now() - killStart < 500) {\n            await new Promise((r) => setTimeout(r, 50));\n            dead = !this.isPidAliveFn(pid);\n          }\n        }\n      }\n\n      this.stateStore.clearState(rec.platform);\n    }\n  }\n\n  async stop(platform: BrowserPlatform): Promise<void> {\n    return this.enqueue(platform, async () => {\n      const rec = this.getRecord(platform);\n      await this.internalStop(rec);\n    });\n  }\n\n  async resetSession(platform: BrowserPlatform): Promise<void> {\n    await this.stop(platform);\n    this.profileStore.clearProfile(platform);\n  }\n\n  async dispose(): Promise<void> {\n    this.disposed = true;\n    const platforms = Array.from(this.records.keys());\n    await Promise.all(platforms.map((p) => this.stop(p)));\n  }\n}\n"
    },
    {
      "path": "src/host/provider-transport.ts",
      "content": "/**\n * dsh-web-tools — secure outbound transport for operator-configured provider\n * endpoints (Issue #9).\n *\n * ## Why this is separate from `generic-fetch`\n *\n * `generic-fetch` guards a URL the *model* chose, and its job is to fetch any\n * public page. A provider endpoint is different: it is operator-configured, it\n * receives a stored API credential, and it may legitimately be an internal\n * gateway. Reusing the page-fetch guard would either block every gateway\n * (unusable) or, if relaxed globally, disarm page fetching. So the two have\n * separate policies and this module owns the provider one.\n *\n * ## What it enforces\n *\n * 1. URL structure: http(s) only, no userinfo, no fragment, explicit port only\n *    when the policy allows it.\n * 2. Host authorization *before* any DNS work: a trusted default, an explicit\n *    operator authorization, or a public host.\n * 3. Address authorization on **every** candidate A/AAAA record, and then a\n *    socket pinned to one of those exact addresses — so the address that was\n *    validated is the address that is connected to. Validating and then letting\n *    a client re-resolve is the DNS-rebinding hole this closes.\n * 4. `redirect: \"error\"` — a 3xx never re-sends the credential to a new origin.\n * 5. Byte-capped bodies and a content-type check before JSON parsing.\n * 6. Proxy use is explicit. When a proxy is configured but the policy does not\n *    authorize it, the request FAILS CLOSED: through a proxy the final DNS and\n *    connection happen at the proxy, so a local check could not substantiate\n *    the destination. Silent degradation is deliberately not an option.\n *\n * @module\n */\nimport { isIP } from \"node:net\";\nimport { lookup as dnsLookup } from \"node:dns\";\nimport { connect as netConnect, type Socket } from \"node:net\";\nimport { connect as tlsConnect, type TLSSocket } from \"node:tls\";\nimport { isPrivateOrRestrictedIp } from \"./fetch-security.ts\";\n\n// ---------------------------------------------------------------------------\n// classification\n// ---------------------------------------------------------------------------\n\n/** Machine codes the transport raises (mapped to UI codes by the caller). */\nexport type TransportErrorCode =\n  | \"invalid-url\"\n  | \"destination-blocked\"\n  | \"proxy-required\"\n  | \"timeout\"\n  | \"network\"\n  | \"invalid-response\"\n  | \"config\"\n  | \"aborted\";\n\nexport class TransportError extends Error {\n  readonly code: TransportErrorCode;\n  readonly status?: number;\n  constructor(code: TransportErrorCode, message: string, status?: number) {\n    super(message);\n    this.name = \"TransportError\";\n    this.code = code;\n    if (status !== undefined) this.status = status;\n  }\n}\n\n/** True for any transport failure (already classified — never re-wrap). */\nexport function isTransportError(value: unknown): value is TransportError {\n  return value instanceof TransportError;\n}\n\n// ---------------------------------------------------------------------------\n// policy\n// ---------------------------------------------------------------------------\n\n/**\n * How much the destination is trusted.\n *  - `official` — the adapter's own built-in endpoint. Trusted by definition;\n *    a loopback default (self-hosted SearXNG) is legitimate here.\n *  - `authorized` — an explicit operator authorization matched this host:port.\n *  - `public` — a user-typed address; must be a public host on https.\n */\nexport type DestinationTrust = \"official\" | \"authorized\" | \"public\";\n\nexport type { OutboundAuthorization } from \"../shared/custom-provider-types.ts\";\nimport type { OutboundAuthorization } from \"../shared/custom-provider-types.ts\";\n\n/** Operator policy for outbound provider requests. */\nexport interface OutboundPolicy {\n  /** Granted targets. */\n  authorizations: OutboundAuthorization[];\n  /** Allow http:// for non-official destinations. Default false. */\n  allowPublicHttp?: boolean;\n  /** Whether proxied requests are permitted for this destination. */\n  allowProxy?: boolean;\n  /** Hard cap on response bytes (default 2 MiB). */\n  maxResponseBytes?: number;\n  /** Connect timeout in ms (default 10s). */\n  connectTimeoutMs?: number;\n  /** Request timeout in ms (default 15s). */\n  requestTimeoutMs?: number;\n}\n\nexport const DEFAULT_MAX_RESPONSE_BYTES = 2 * 1024 * 1024;\nconst DEFAULT_CONNECT_TIMEOUT_MS = 10_000;\nconst DEFAULT_REQUEST_TIMEOUT_MS = 15_000;\n\n/** Operator-granted outbound destinations (shared registry). */\nexport const OUTBOUND_AUTHORIZATIONS: OutboundAuthorization[] = [];\n\n/** Update global outbound authorizations from live settings. */\nexport function setGlobalOutboundAuthorizations(auths: readonly OutboundAuthorization[]): void {\n  OUTBOUND_AUTHORIZATIONS.length = 0;\n  OUTBOUND_AUTHORIZATIONS.push(...auths);\n}\n\n/** Match a host against one authorization entry. */\nexport function hostMatchesAuthorization(host: string, entry: OutboundAuthorization): boolean {\n  const h = host.toLowerCase().replace(/^\\[|\\]$/g, \"\");\n  const pattern = entry.host.toLowerCase().replace(/^\\[|\\]$/g, \"\");\n  if (pattern.startsWith(\".\")) return h === pattern.slice(1) || h.endsWith(pattern);\n  return h === pattern;\n}\n\n/** The authorization covering this host:port, if any. */\nexport function findAuthorization(\n  host: string,\n  port: number,\n  policy: OutboundPolicy,\n): OutboundAuthorization | undefined {\n  return policy.authorizations.find(\n    (entry) => hostMatchesAuthorization(host, entry) && (entry.port === undefined || entry.port === port),\n  );\n}\n\n// ---------------------------------------------------------------------------\n// URL structural validation\n// ---------------------------------------------------------------------------\n\n/** Reject URL shapes that are never legitimate for a provider endpoint. */\nexport function assertEndpointUrl(rawUrl: string): URL {\n  if (typeof rawUrl !== \"string\" || rawUrl.trim() === \"\") {\n    throw new TransportError(\"invalid-url\", \"Provider endpoint URL is empty\");\n  }\n  let parsed: URL;\n  try {\n    parsed = new URL(rawUrl.trim());\n  } catch {\n    throw new TransportError(\"invalid-url\", \"Provider endpoint URL is not a valid URL\");\n  }\n  if (parsed.protocol !== \"http:\" && parsed.protocol !== \"https:\") {\n    throw new TransportError(\"invalid-url\", `Unsupported protocol \"${parsed.protocol}\" for a provider endpoint`);\n  }\n  if (parsed.username || parsed.password) {\n    throw new TransportError(\"invalid-url\", \"Provider endpoint URL must not embed userinfo credentials\");\n  }\n  // A fragment is never meaningful to an API and may be used to smuggle text\n  // past a naive echo in logs.\n  if (parsed.hash) {\n    throw new TransportError(\"invalid-url\", \"Provider endpoint URL must not contain a fragment\");\n  }\n  if (!parsed.hostname) {\n    throw new TransportError(\"invalid-url\", \"Provider endpoint URL is missing a hostname\");\n  }\n  return parsed;\n}\n\n// ---------------------------------------------------------------------------\n// header hygiene\n// ---------------------------------------------------------------------------\n\n/** Header names a custom provider may never set (host/transport integrity). */\nconst RESERVED_HEADERS = new Set([\n  \"host\",\n  \"connection\",\n  \"content-length\",\n  \"transfer-encoding\",\n  \"upgrade\",\n  \"keep-alive\",\n  \"te\",\n  \"trailer\",\n  \"proxy-authorization\",\n  \"proxy-connection\",\n]);\n\n/** RFC 7230 token — the only legal shape for a header field name. */\nconst HEADER_NAME_RE = /^[!#$%&'*+\\-.^_`|~0-9A-Za-z]+$/;\n\n/**\n * Validate one user-supplied header name.\n * @throws {TransportError} on a reserved or malformed name.\n */\nexport function assertHeaderName(name: string): void {\n  if (typeof name !== \"string\" || !HEADER_NAME_RE.test(name)) {\n    throw new TransportError(\"config\", `Invalid header name (not an RFC 7230 token)`);\n  }\n  if (RESERVED_HEADERS.has(name.toLowerCase())) {\n    throw new TransportError(\"config\", `Header \"${name}\" is reserved and cannot be overridden`);\n  }\n}\n\n/** Upper bound on any single mapped string field. */\nexport const MAX_MAPPED_STRING_CHARS = 4000;\n\n/**\n * Truncate at a Unicode-safe boundary.\n *\n * `String.prototype.slice` operates on UTF-16 code units, so a naive cut can\n * split a surrogate pair and leave a lone surrogate in the output (invalid\n * text that corrupts downstream JSON/tool contexts). This walks back off a\n * dangling high surrogate instead.\n */\nexport function truncateUnicodeSafe(value: string, maxChars = MAX_MAPPED_STRING_CHARS): string {\n  if (value.length <= maxChars) return value;\n  let end = maxChars;\n  const last = value.charCodeAt(end - 1);\n  if (last >= 0xd800 && last <= 0xdbff) end -= 1; // dangling high surrogate\n  return `${value.slice(0, end)}…`;\n}\n\n// ---------------------------------------------------------------------------\n// dns + connect\n// ---------------------------------------------------------------------------\n\n/** One resolved address record. */\nexport interface ResolvedAddress {\n  address: string;\n  family: number;\n}\n\n/** Injectable DNS resolver (tests never touch the network). */\nexport type LookupAllFn = (hostname: string) => Promise<ResolvedAddress[]>;\n\nexport const defaultLookupAll: LookupAllFn = (hostname) =>\n  new Promise((resolve, reject) => {\n    dnsLookup(hostname, { all: true }, (err, addresses) => {\n      if (err) reject(err);\n      else resolve(addresses as ResolvedAddress[]);\n    });\n  });\n\n/**\n * Asynchronously probe whether a hostname resolves to private/loopback/restricted IP addresses.\n * Returns true if any candidate A/AAAA record is private/loopback/restricted.\n * Returns false for public IPs or on lookup failure.\n */\nexport async function resolvesToPrivateIp(\n  hostname: string,\n  lookupAll: LookupAllFn = defaultLookupAll,\n): Promise<boolean> {\n  const clean = hostname.toLowerCase().replace(/^\\[|\\]$/g, \"\");\n  if (isIP(clean) !== 0) {\n    return isPrivateOrRestrictedIp(clean);\n  }\n  try {\n    const records = await lookupAll(clean);\n    return Array.isArray(records) && records.some((r) => isPrivateOrRestrictedIp(r.address));\n  } catch {\n    return false;\n  }\n}\n\n/**\n * Unconditionally blocked destination check for cloud instance metadata and link-local addresses.\n *\n * Covers:\n *  - 169.254.0.0/16 (IPv4 link-local & cloud metadata e.g. AWS/Azure/GCP 169.254.169.254)\n *  - fe80::/10 (IPv6 link-local unicast: fe80:: through febf::, including fe80::1, fe90::1, etc.)\n *  - IPv4-mapped IPv6 forms of 169.254.0.0/16:\n *      * Dotted-decimal: ::ffff:169.254.x.x, 0:0:0:0:0:ffff:169.254.x.x\n *      * Hexadecimal: ::ffff:a9fe:xxxx, 0:0:0:0:0:ffff:a9fe:xxxx (where 169.254 in hex is 0xa9fe)\n *  - fd00:ec2::254 (IMDSv6)\n *\n * This check is absolute and invariant: even if the operator explicitly authorizes a private\n * network with `allowPrivate: true`, these targets are NEVER permitted.\n */\nexport function isCloudMetadataOrLinkLocal(address: string): boolean {\n  const clean = address.toLowerCase().replace(/^\\[|\\]$/g, \"\");\n\n  // 1. IPv4-mapped IPv6: unmap to standard IPv4 or check hex words\n  if (clean.startsWith(\"::ffff:\") || clean.startsWith(\"0:0:0:0:0:ffff:\")) {\n    const tail = clean.split(\"ffff:\").pop() ?? \"\";\n    if (tail.includes(\".\")) {\n      // Dotted-decimal, e.g. ::ffff:169.254.169.254\n      const parts = tail.split(\".\").map((p) => Number.parseInt(p, 10));\n      if (parts.length === 4 && parts[0] === 169 && parts[1] === 254) {\n        return true;\n      }\n    } else {\n      // Hex form, e.g. ::ffff:a9fe:a9fe or ::ffff:a9fe:1\n      const hexParts = tail.split(\":\");\n      if (hexParts.length >= 1) {\n        const firstHex = Number.parseInt(hexParts[0], 16);\n        // 169.254 in hex is 0xa9fe (169 = 0xa9, 254 = 0xfe)\n        if (firstHex === 0xa9fe) {\n          return true;\n        }\n      }\n    }\n  }\n\n  // 2. Direct IPv4 Link-Local & Cloud Metadata (169.254.0.0/16)\n  if (clean.startsWith(\"169.254.\")) {\n    return true;\n  }\n  const v4Parts = clean.split(\".\").map((p) => Number.parseInt(p, 10));\n  if (v4Parts.length === 4 && v4Parts[0] === 169 && v4Parts[1] === 254) {\n    return true;\n  }\n\n  // 3. IPv6 Link-Local (fe80::/10: first 10 bits 1111 1110 10 -> 0xfe80..0xfebf)\n  const firstWord = clean.split(\":\")[0];\n  if (firstWord && firstWord.length <= 4) {\n    const val = Number.parseInt(firstWord, 16);\n    if (!Number.isNaN(val) && (val & 0xffc0) === 0xfe80) {\n      return true;\n    }\n  }\n  if (/^fe[89ab][0-9a-f](:|$)/i.test(clean)) {\n    return true;\n  }\n\n  // 4. Well-known IMDSv6 endpoint\n  if (clean === \"fd00:ec2::254\") {\n    return true;\n  }\n\n  return false;\n}\n\n/**\n * Decide whether one resolved address may be connected to.\n *\n * `allowPrivate` is the single gate for loopback/RFC1918/link-local: it is true\n * only for a built-in provider's own official endpoint or for a host the\n * operator explicitly authorized with `allowPrivate`.\n *\n * @throws {TransportError} `destination-blocked` when it may not.\n */\nexport function assertAddressAllowed(address: string, allowPrivate: boolean): void {\n  // Cloud metadata and link-local (169.254.0.0/16, fe80::/10) are UNCONDITIONALLY\n  // blocked. Even with explicit allowPrivate authorization, no search provider\n  // is ever permitted to reach cloud instance metadata or link-local endpoints.\n  if (isCloudMetadataOrLinkLocal(address)) {\n    throw new TransportError(\n      \"destination-blocked\",\n      `Access to cloud metadata or link-local address ${address} is strictly forbidden`,\n    );\n  }\n  if (allowPrivate) return;\n  if (isPrivateOrRestrictedIp(address)) {\n    throw new TransportError(\n      \"destination-blocked\",\n      `Resolved address ${address} is private, loopback, or link-local and this destination is not authorized for it`,\n    );\n  }\n}\n\n/** Injectable socket connector (tests substitute a fake). */\nexport type ConnectFn = (options: {\n  address: string;\n  port: number;\n  servername: string;\n  useTls: boolean;\n  timeoutMs: number;\n  signal?: AbortSignal;\n}) => Socket | TLSSocket;\n\n/** Default connector: real TCP/TLS, pinned to one validated address. */\nexport const defaultConnect: ConnectFn = ({ address, port, servername, useTls, timeoutMs, signal }) => {\n  if (useTls) {\n    return tlsConnect(\n      { host: address, port, servername, rejectUnauthorized: true, ...(signal ? { signal } : {}) },\n      undefined,\n    );\n  }\n  const socket = netConnect({ host: address, port, ...(signal ? { signal } : {}) });\n  socket.setTimeout(timeoutMs);\n  return socket;\n};\n\n// ---------------------------------------------------------------------------\n// request / response\n// ---------------------------------------------------------------------------\n\n/** One outbound provider request. */\nexport interface TransportRequest {\n  url: string;\n  method: \"GET\" | \"POST\";\n  headers: Record<string, string>;\n  /** Serialized request body (POST only). Never logged. */\n  body?: string;\n  /** Structural description for diagnostics — no secrets. */\n  label: string;\n  trust: DestinationTrust;\n  policy: OutboundPolicy;\n  signal?: AbortSignal;\n  /**\n   * Skip the public-address check for this request. Only the built-in adapters\n   * set this, and only for their own hardcoded official endpoint.\n   */\n  builtInOfficial?: boolean;\n}\n\n/** One outbound provider response. */\nexport interface TransportResponse {\n  status: number;\n  ok: boolean;\n  contentType: string;\n  /** Parsed JSON when the body parsed; otherwise undefined. */\n  json?: unknown;\n  /** Raw text (bounded) when JSON parsing was attempted or content was text. */\n  text: string;\n  /** True when the body exceeded the cap and was truncated. */\n  truncated: boolean;\n  headers: Headers;\n}\n\n/** Injectable seams so tests never open a socket. */\nexport interface TransportDeps {\n  lookupAll: LookupAllFn;\n  connect: ConnectFn;\n  /** Resolve a proxy URL, or undefined when no proxy is configured. */\n  proxyUrl?: () => string | undefined;\n  /** Build a dispatcher for a proxy URL (undici ProxyAgent). */\n  proxyDispatcher?: (proxyUrl: string) => Promise<unknown>;\n  /** Bound the whole request (tests inject an instant timer). */\n  now: () => number;\n}\n\n/** Result of a DNS pre-flight (also used by the connect guard). */\nexport interface DnsPreflight {\n  addresses: ResolvedAddress[];\n  allowPrivate: boolean;\n}\n\n/**\n * Resolve and validate every candidate address for a destination.\n * @throws {TransportError} when any candidate is disallowed.\n */\nexport async function preflightDns(\n  hostname: string,\n  trust: DestinationTrust,\n  policy: OutboundPolicy,\n  deps: Pick<TransportDeps, \"lookupAll\">,\n): Promise<DnsPreflight> {\n  const host = hostname.toLowerCase().replace(/^\\[|\\]$/g, \"\");\n  const literal = isIP(host);\n\n  // A literal address bypasses DNS entirely.\n  if (literal !== 0) {\n    const allowPrivate = trust === \"official\" || isAuthorizedPrivate(host, policy);\n    assertAddressAllowed(host, allowPrivate);\n    return { addresses: [{ address: host, family: literal }], allowPrivate };\n  }\n\n  let records: ResolvedAddress[];\n  try {\n    records = await deps.lookupAll(host);\n  } catch (err) {\n    throw new TransportError(\"network\", `DNS lookup failed for \"${host}\": ${err instanceof Error ? err.message : String(err)}`);\n  }\n  if (!records || records.length === 0) {\n    throw new TransportError(\"network\", `DNS lookup for \"${host}\" returned no addresses`);\n  }\n\n  const allowPrivate = trust === \"official\" || policy.authorizations.some((entry) => entry.allowPrivate && hostMatchesAuthorization(host, entry));\n  for (const record of records) {\n    assertAddressAllowed(record.address, allowPrivate);\n  }\n  return { addresses: records, allowPrivate };\n}\n\nfunction isAuthorizedPrivate(host: string, policy: OutboundPolicy): boolean {\n  return policy.authorizations.some((entry) => entry.allowPrivate && hostMatchesAuthorization(host, entry));\n}\n\n/**\n * Fetch one provider endpoint under an explicit outbound policy.\n *\n * @throws {TransportError} on any policy, DNS, network, or size violation.\n */\nexport async function transact(\n  request: TransportRequest,\n  overrides: Partial<TransportDeps> = {},\n): Promise<TransportResponse> {\n  const deps: TransportDeps = {\n    lookupAll: overrides.lookupAll ?? defaultLookupAll,\n    connect: overrides.connect ?? defaultConnect,\n    proxyUrl: overrides.proxyUrl,\n    proxyDispatcher: overrides.proxyDispatcher,\n    now: overrides.now ?? (() => Date.now()),\n  };\n\n  const parsed = assertEndpointUrl(request.url);\n  const policy = request.policy;\n  const port = parsed.port ? Number(parsed.port) : parsed.protocol === \"https:\" ? 443 : 80;\n  const maxBytes = policy.maxResponseBytes ?? DEFAULT_MAX_RESPONSE_BYTES;\n\n  // ---- 1. scheme & host authorization -----------------------------------\n  const authorization = findAuthorization(parsed.hostname, port, policy);\n  if (parsed.protocol === \"http:\") {\n    const isAuthorizedHttp = authorization?.allowHttp === true;\n    const allowed = request.trust === \"official\"\n      ? isLoopbackHost(parsed.hostname)\n      : (policy.allowPublicHttp === true || isAuthorizedHttp);\n    if (!allowed) {\n      throw new TransportError(\n        \"destination-blocked\",\n        \"Plain http:// endpoints are only allowed for loopback defaults or an explicitly authorized target\",\n      );\n    }\n  }\n\n  // ---- 2. host authorization (before DNS) --------------------------------\n  if (request.trust === \"authorized\" && !authorization) {\n    throw new TransportError(\"destination-blocked\", `Destination \"${parsed.hostname}:${port}\" is not authorized`);\n  }\n  if ((request.trust === \"official\" || request.trust === \"authorized\") && authorization?.allowHttp && parsed.protocol === \"http:\") {\n    // explicit http grant for a non-loopback authorized target\n  }\n\n  // ---- 3. header hygiene -------------------------------------------------\n  for (const name of Object.keys(request.headers)) assertHeaderName(name);\n\n  // ---- 4. DNS pre-flight ------------------------------------------------\n  // Runs BEFORE the proxy decision because the resolved address decides it: an\n  // ambient HTTP proxy cannot reach private/LAN space (it dials from wherever\n  // it runs), so a destination that resolves to a private address must be\n  // dialed directly even when Windows has a system proxy configured. Without\n  // this, a self-hosted source on 192.168.x.x could be saved and authorized and\n  // still fail every search with `proxy-required`.\n  const preflight = await preflightDns(parsed.hostname, request.trust, policy, deps);\n  const pinned = preflight.addresses[0];\n  const useTls = parsed.protocol === \"https:\";\n  const privateDestination = preflight.addresses.some((record) => isPrivateOrRestrictedIp(record.address));\n\n  // ---- 5. proxy decision (fail closed) ----------------------------------\n  // Loopback and private destinations are connected directly: this only\n  // bypasses proxy ROUTING, never the allowHttp/allowPrivate authorization or\n  // the pinned connection below.\n  const directDial = isLoopbackHost(parsed.hostname) || privateDestination;\n  const proxyUrl = directDial ? undefined : deps.proxyUrl?.();\n  let dispatcher: unknown;\n  if (proxyUrl !== undefined && !(request.builtInOfficial === true) && !isLoopbackUrl(parsed.href)) {\n    if (policy.allowProxy !== true) {\n      throw new TransportError(\n        \"proxy-required\",\n        \"A proxy is configured and this destination is not authorized for proxied requests: the final DNS resolution and connection would happen at the proxy, so the destination cannot be verified locally\",\n      );\n    }\n    dispatcher = await deps.proxyDispatcher?.(proxyUrl);\n  }\n\n  // Only attach the custom dispatcher when we are NOT pinning, i.e. built-in\n  // official endpoints (whose host is trusted by construction) and proxied\n  // requests (where the proxy performs the connection).\n  const signal = combineAbort(request.signal, policy.requestTimeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS);\n\n  const init: Record<string, unknown> = {\n    method: request.method,\n    headers: request.headers,\n    // A 3xx must never re-send the credential to another origin.\n    redirect: \"error\",\n    signal: signal.signal,\n    ...(request.body !== undefined ? { body: request.body } : {}),\n  };\n  let pinnedDispatcher: any = undefined;\n  if (dispatcher !== undefined) {\n    init.dispatcher = dispatcher;\n  } else if (request.trust === \"official\") {\n    // Built-in official endpoint: host is trusted by construction (no DNS\n    // rebinding incentive — the credential goes where it was always going),\n    // so the platform fetch resolves and connects normally. The redirect and\n    // size guards above still apply.\n  } else {\n    // Operator-typed destination: always pinned to a pre-validated address.\n    pinnedDispatcher = await createPinnedDispatcher({\n      address: pinned.address,\n      port,\n      servername: parsed.hostname,\n      useTls,\n      connectTimeoutMs: policy.connectTimeoutMs ?? DEFAULT_CONNECT_TIMEOUT_MS,\n      connect: deps.connect,\n      signal: signal.signal,\n    });\n    init.dispatcher = pinnedDispatcher;\n  }\n\n  let response: Response;\n  try {\n    response = await fetch(parsed.href, init as RequestInit);\n  } catch (err) {\n    signal.dispose();\n    if (pinnedDispatcher && typeof pinnedDispatcher.destroy === \"function\") {\n      try { await pinnedDispatcher.destroy(); } catch {}\n    }\n    if (request.signal?.aborted) throw new TransportError(\"aborted\", `${request.label} aborted by caller`);\n    if (isTransportError(err)) throw err;\n    const cause = describeCause(err);\n    if (signal.timedOut()) throw new TransportError(\"timeout\", `${request.label} timed out (${cause})`);\n    // A rejected pinned connect surfaces here — surface the block, not a bare\n    // \"fetch failed\", so the UI can explain the denial.\n    if (isDestinationBlocked(cause)) throw new TransportError(\"destination-blocked\", `${request.label}: ${cause}`);\n    throw new TransportError(\"network\", `${request.label} failed: ${cause}`);\n  }\n\n  try {\n    // ---- 6. content-type + size bounded read -----------------------------\n    const contentType = response.headers.get(\"content-type\") ?? \"\";\n    const contentLength = Number(response.headers.get(\"content-length\") ?? \"0\");\n    if (Number.isFinite(contentLength) && contentLength > maxBytes) {\n      throw new TransportError(\"invalid-response\", `${request.label} response is ${contentLength} bytes, above the ${maxBytes}-byte cap`);\n    }\n\n    const { text, truncated } = await readBounded(response, maxBytes, signal.signal);\n    let json: unknown;\n    if (looksLikeJson(contentType, text)) {\n      try {\n        json = JSON.parse(text);\n      } catch {\n        throw new TransportError(\"invalid-response\", `${request.label} returned a body that is not valid JSON`);\n      }\n    }\n    return { status: response.status, ok: response.ok, contentType, json, text, truncated, headers: response.headers };\n  } finally {\n    signal.dispose();\n    if (pinnedDispatcher && typeof pinnedDispatcher.destroy === \"function\") {\n      try { await pinnedDispatcher.destroy(); } catch {}\n    }\n  }\n}\n\n/** Content-type gate for JSON parsing (a missing type still parses). */\nfunction looksLikeJson(contentType: string, text: string): boolean {\n  const type = contentType.toLowerCase();\n  if (type.includes(\"json\")) return true;\n  if (type === \"\" || type.includes(\"text/plain\")) {\n    const head = text.trimStart()[0];\n    return head === \"{\" || head === \"[\";\n  }\n  return false;\n}\n\n/** Read a response body up to `maxBytes`. */\nasync function readBounded(\n  response: Response,\n  maxBytes: number,\n  signal: AbortSignal,\n): Promise<{ text: string; truncated: boolean }> {\n  if (response.body === null) return { text: \"\", truncated: false };\n  const reader = response.body.getReader();\n  const chunks: Uint8Array[] = [];\n  let total = 0;\n  let truncated = false;\n  try {\n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      if (signal.aborted) throw new TransportError(\"aborted\", \"response read aborted\");\n      if (value === undefined) continue;\n      total += value.byteLength;\n      if (total > maxBytes) {\n        const keep = value.byteLength - (total - maxBytes);\n        if (keep > 0) chunks.push(value.subarray(0, keep));\n        truncated = true;\n        break;\n      }\n      chunks.push(value);\n    }\n  } finally {\n    // A capped read must not leave the socket streaming.\n    if (truncated || signal.aborted) await reader.cancel().catch(() => {});\n  }\n  const merged = new Uint8Array(chunks.reduce((n, c) => n + c.byteLength, 0));\n  let offset = 0;\n  for (const c of chunks) {\n    merged.set(c, offset);\n    offset += c.byteLength;\n  }\n  return { text: new TextDecoder(\"utf-8\", { fatal: false }).decode(merged), truncated };\n}\n\n/** Build an undici dispatcher whose connections are pinned to one address. */\nexport async function createPinnedDispatcher(options: {\n  address: string;\n  port: number;\n  servername: string;\n  useTls: boolean;\n  connectTimeoutMs: number;\n  connect: ConnectFn;\n  signal: AbortSignal;\n}): Promise<unknown> {\n  const undici = (await import(\"undici\").catch(() => undefined)) as\n    | { Agent?: new (opts: unknown) => unknown; buildConnector?: (opts: unknown) => unknown }\n    | undefined;\n  if (!undici?.Agent) {\n    // FAIL CLOSED. Without a dispatcher there is no way to bind the connection\n    // to the address that was just validated, so the request would re-resolve\n    // the name and re-open the DNS-rebinding hole this guard exists to close.\n    // Refusing is the only safe option; silently degrading to a plain fetch is\n    // exactly the failure mode that makes an SSRF guard worthless.\n    throw new TransportError(\n      \"network\",\n      \"Secure transport unavailable: the undici Agent required to pin the connection to a validated address could not be loaded\",\n    );\n  }\n\n  // Use Undici's buildConnector if default connector is active, ensuring full TLS,\n  // ALPN, and HTTP/1.1 socket lifecycle handling while pinning DNS to options.address.\n  let baseConnector: any;\n  if (options.connect === defaultConnect && typeof undici.buildConnector === \"function\") {\n    baseConnector = undici.buildConnector({\n      lookup: (_hostname: string, _opts: any, cb: (err: Error | null, addresses: Array<{ address: string; family: number }>) => void) => {\n        const family = options.address.includes(\":\") ? 6 : 4;\n        cb(null, [{ address: options.address, family }]);\n      },\n      timeout: options.connectTimeoutMs,\n    });\n  }\n\n  const connector = (opts: { hostname?: string; port?: string | number; servername?: string }, cb: (err: Error | null, socket: any) => void) => {\n    // undici passes the authority it is about to dial. It must be exactly the\n    // authority this transport approved, otherwise the client resolved (or\n    // was redirected to) something we never authorized.\n    const requestedPort = opts.port === undefined ? options.port : Number(opts.port);\n    const requestedHost = String(opts.hostname ?? options.servername);\n    if (requestedHost !== options.servername || !Number.isFinite(requestedPort) || requestedPort !== options.port) {\n      const err = new TransportError(\n        \"destination-blocked\",\n        `Connection attempt for unapproved authority ${requestedHost}:${String(requestedPort)}`,\n      );\n      if (typeof cb === \"function\") cb(err, null);\n      else throw err;\n      return;\n    }\n\n    if (baseConnector) {\n      baseConnector(opts, cb);\n      return;\n    }\n\n    // Custom or mock connector path:\n    try {\n      const socket = options.connect({\n        address: options.address,\n        port: options.port,\n        servername: options.servername,\n        useTls: options.useTls,\n        timeoutMs: options.connectTimeoutMs,\n        signal: options.signal,\n      });\n\n      if (typeof cb === \"function\") {\n        if (\"once\" in socket) {\n          const onConnect = () => {\n            cleanup();\n            cb(null, socket);\n          };\n          const onError = (err: Error) => {\n            cleanup();\n            cb(err, null);\n          };\n          const cleanup = () => {\n            socket.removeListener(\"connect\", onConnect);\n            socket.removeListener(\"secureConnect\", onConnect);\n            socket.removeListener(\"error\", onError);\n          };\n          socket.once(\"error\", onError);\n          if (options.useTls) {\n            socket.once(\"secureConnect\", onConnect);\n          } else {\n            socket.once(\"connect\", onConnect);\n          }\n        } else {\n          cb(null, socket);\n        }\n      }\n      return socket;\n    } catch (err: any) {\n      if (typeof cb === \"function\") cb(err instanceof Error ? err : new Error(String(err)), null);\n      else throw err;\n    }\n  };\n\n  return new undici.Agent({\n    connect: connector,\n  });\n}\n\n// ---------------------------------------------------------------------------\n// helpers\n// ---------------------------------------------------------------------------\n\n/** Caller abort + request timeout, merged with explicit cause tracking. */\nfunction combineAbort(\n  external: AbortSignal | undefined,\n  timeoutMs: number,\n): { signal: AbortSignal; dispose: () => void; timedOut: () => boolean } {\n  const controller = new AbortController();\n  let timedOut = false;\n  let timer: ReturnType<typeof setTimeout> | undefined;\n\n  const onAbort = () => {\n    if (timer) {\n      clearTimeout(timer);\n      timer = undefined;\n    }\n    controller.abort(external?.reason);\n  };\n  if (external) {\n    if (external.aborted) controller.abort(external.reason);\n    else external.addEventListener(\"abort\", onAbort, { once: true });\n  }\n  if (Number.isFinite(timeoutMs) && timeoutMs > 0) {\n    timer = setTimeout(() => {\n      timedOut = true;\n      controller.abort(new Error(`request timed out after ${timeoutMs}ms`));\n    }, timeoutMs);\n    timer.unref?.();\n  }\n  return {\n    signal: controller.signal,\n    dispose: () => {\n      if (timer) clearTimeout(timer);\n      timer = undefined;\n      if (external) external.removeEventListener(\"abort\", onAbort);\n    },\n    timedOut: () => timedOut,\n  };\n}\n\n/** Flatten an undici error's cause chain into one diagnostic string. */\nfunction describeCause(err: unknown): string {\n  const top = err instanceof Error ? err.message : String(err);\n  let cause: unknown = (err as { cause?: unknown })?.cause;\n  const seen = new Set<unknown>([err]);\n  while (cause !== undefined && cause !== null && !seen.has(cause)) {\n    seen.add(cause);\n    if (isTransportError(cause)) return cause.message;\n    const message = cause instanceof Error ? cause.message : String(cause);\n    if (message && message !== top) return message;\n    cause = (cause as { cause?: unknown })?.cause;\n  }\n  return top;\n}\n\n/** True when a flattened error came from the destination guard. */\nfunction isDestinationBlocked(message: string): boolean {\n  return /unapproved authority|not authorized|private, loopback, or link-local|blocked/i.test(message);\n}\n\nexport function isLoopbackHost(hostname: string): boolean {\n  const host = hostname.toLowerCase().replace(/^\\[|\\]$/g, \"\");\n  if (host === \"localhost\" || host === \"::1\" || host === \"0:0:0:0:0:0:0:1\") return true;\n  if (/^127\\.\\d{1,3}\\.\\d{1,3}\\.\\d{1,3}$/.test(host)) {\n    return Number(host.split(\".\")[0]) === 127;\n  }\n  return false;\n}\n\n/**\n * Whether a URL targets the loopback host. Loopback targets are always dialed\n * directly (never through a proxy): there is no DNS rebinding concern and a\n * local instance must not be tunneled to an ambient internet proxy.\n */\nexport function isLoopbackUrl(urlStr: string): boolean {\n  try {\n    return isLoopbackHost(new URL(urlStr).hostname);\n  } catch {\n    return false;\n  }\n}\n\n/**\n * Whether a hostname is an IP literal in private/loopback space or a named local domain.\n * Normal public domain names (e.g. example.com, api.tavily.com) return false.\n */\nexport function isLocalOrPrivateHost(hostname: string): boolean {\n  const clean = hostname.toLowerCase().replace(/^\\[|\\]$/g, \"\");\n  if (isLoopbackHost(clean)) return true;\n  if (isCloudMetadataOrLinkLocal(clean)) return true;\n  const ipVer = isIP(clean);\n  if (ipVer !== 0) {\n    return isPrivateOrRestrictedIp(clean);\n  }\n  return (\n    clean === \"localhost\" ||\n    clean.endsWith(\".localhost\") ||\n    clean.endsWith(\".local\") ||\n    clean.endsWith(\".internal\") ||\n    clean.endsWith(\".lan\") ||\n    clean.endsWith(\".localdomain\")\n  );\n}\n"
